func stubControllerAdmission(t *testing.T, marker bool, localErr error, full func(int32) error) *admissionStubs {
	t.Helper()
	stubs := &admissionStubs{}
	previousMarker := controllerMarkerPresent
	previousBaked := controllerBakedInputsPresent
	previousLocal, previousFull := controllerLocalAdmissionProduction, controllerBootstrapProduction
	previousMin, previousMax := controllerAdmissionMinBackoff, controllerAdmissionMaxBackoff
	controllerMarkerPresent = func() (bool, error) { return marker, nil }
	controllerBakedInputsPresent = func() (bool, error) { return true, nil }
	controllerLocalAdmissionProduction = func(context.Context, Config) error {
		stubs.local.Add(1)
		return localErr
	}
	controllerBootstrapProduction = func(ctx context.Context, _ Config) error {
		return full(stubs.full.Add(1))
	}
	controllerAdmissionMinBackoff, controllerAdmissionMaxBackoff = time.Millisecond, 5*time.Millisecond
	t.Cleanup(func() {
		controllerMarkerPresent = previousMarker
		controllerBakedInputsPresent = previousBaked
		controllerLocalAdmissionProduction, controllerBootstrapProduction = previousLocal, previousFull
		controllerAdmissionMinBackoff, controllerAdmissionMaxBackoff = previousMin, previousMax
	})
	return stubs
}

func startControllerAdmission(ctx context.Context, cfg Config, clockCheck func() error) (*controllerAdmission, error) {
	offline, err := offlineRestartAdmission(cfg)
	if err != nil {
		return nil, err
	}
	admission := &controllerAdmission{offline: offline, done: make(chan struct{})}
	if !offline {
		if err := admitControllerBootstrap(ctx, cfg, clockCheck); err != nil {
			return nil, err
		}
		close(admission.done)
		return admission, nil
	}
	if err := controllerLocalAdmissionProduction(ctx, cfg); err != nil {
		return nil, fmt.Errorf("offline controller restart admission: %w", err)
	}
	log.Printf("controller %s passed local restart admission; starting broker routes before OCI re-verification", cfg.NATS.Instance)
	runCtx, cancel := context.WithCancel(ctx)
	admission.cancel, admission.stopped = cancel, make(chan struct{})
	go func() {
		defer close(admission.stopped)
		backoff := controllerAdmissionMinBackoff
		for attempt := 1; ; attempt++ {
			err := admitControllerBootstrap(runCtx, cfg, clockCheck)
			if err == nil {
				log.Printf("controller %s passed full restart admission after %d attempt(s)", cfg.NATS.Instance, attempt)
				close(admission.done)
				return
			}
			if runCtx.Err() != nil {
				return
			}
			delay := backoff + time.Duration(rand.Int64N(int64(backoff)/5+1))
			log.Printf("full controller restart admission attempt %d: %v; authority held, broker routes stay up, retrying in %s",
				attempt, err, delay.Round(time.Second))
			backoff = min(backoff*2, controllerAdmissionMaxBackoff)
			select {
			case <-runCtx.Done():
				return
			case <-time.After(delay):
			}
		}
	}()
	return admission, nil
}

func (admission *controllerAdmission) stop() {
	if admission.cancel != nil {
		admission.cancel()
		<-admission.stopped
	}
}

func (admission *controllerAdmission) wait(ctx context.Context) error {
	select {
	case <-admission.done:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func admitControllerBootstrap(ctx context.Context, cfg Config, clockCheck func() error) error {
	present, err := controllerProductionInputsPresent()
	if err != nil {
		return err
	}
	if !present {
		return errors.New("production controller requires accepted identity or baked bootstrap inputs")
	}
	if clockCheck == nil {
		return errors.New("production controller NTP clock check is unavailable")
	}
	if err := clockCheck(); err != nil {
		return fmt.Errorf("production controller startup NTP clock health: %w", err)
	}
	return controllerBootstrapProduction(ctx, cfg)
}

func shortFounderBackoff(t *testing.T) {
	t.Helper()
	previousMin, previousMax := controllerFounderMinBackoff, controllerFounderMaxBackoff
	controllerFounderMinBackoff, controllerFounderMaxBackoff = time.Millisecond, 5*time.Millisecond
	t.Cleanup(func() { controllerFounderMinBackoff, controllerFounderMaxBackoff = previousMin, previousMax })
}

func superviseFounderAndWaitCluster(ctx context.Context, waitCluster, foundPeers func(context.Context) error,
) (*bootstrapstart.FounderSupervisor, func(), error) {
	if foundPeers == nil {
		return nil, func() {}, waitCluster(ctx)
	}
	founderCtx, cancel := context.WithCancel(ctx)
	supervisor := &bootstrapstart.FounderSupervisor{Found: foundPeers,
		MinBackoff: controllerFounderMinBackoff, MaxBackoff: controllerFounderMaxBackoff}
	done := make(chan struct{})
	go func() {
		defer close(done)
		supervisor.Supervise(founderCtx)
	}()
	var once sync.Once
	stop := func() {
		once.Do(func() {
			cancel()
			timer := time.NewTimer(controllerFounderJoinTimeout)
			defer timer.Stop()
			select {
			case <-done:
			case <-timer.C:
				slog.WarnContext(ctx, "founder did not stop within its join bound; continuing shutdown",
					observability.ComponentKey, "founder", "bound", controllerFounderJoinTimeout)
			}
		})
	}
	if err := waitCluster(ctx); err != nil {
		stop()
		return nil, func() {}, err
	}
	return supervisor, stop, nil
}

func (supervisor *FounderSupervisor) Supervise(ctx context.Context) bool {
	logger := supervisor.Logger
	if logger == nil {
		logger = slog.Default()
	}
	minimum, maximum := supervisor.MinBackoff, supervisor.MaxBackoff
	if minimum <= 0 {
		minimum = defaultFounderMinBackoff
	}
	if maximum < minimum {
		maximum = max(defaultFounderMaxBackoff, minimum)
	}
	after := supervisor.After
	if after == nil {
		after = time.After
	}
	if supervisor.Found == nil {
		supervisor.set(FounderStatus{Phase: FounderPhaseOperatorAction, LastError: "founder is not configured"})
		logger.Error("seed founder worker is not configured")
		return false
	}
	backoff := minimum
	for attempt := 1; ; attempt++ {
		if ctx.Err() != nil {
			supervisor.set(FounderStatus{Phase: FounderPhaseStopped, Attempt: attempt - 1})
			return false
		}
		supervisor.set(FounderStatus{Phase: FounderPhaseRunning, Attempt: attempt})
		err := supervisor.Found(ctx)
		if err == nil {
			supervisor.set(FounderStatus{Phase: FounderPhaseComplete, Attempt: attempt})
			logger.Info("seed founder completed every planned peer", "attempt", attempt)
			return true
		}
		if ctx.Err() != nil {
			supervisor.set(FounderStatus{Phase: FounderPhaseStopped, Attempt: attempt})
			return false
		}
		phase, delay := FounderPhaseRetrying, backoff
		if founderNeedsOperator(err) {
			phase, delay = FounderPhaseOperatorAction, maximum
		}
		// Up to 20% jitter keeps restarted seeds from retrying OCI in lockstep.
		delay += time.Duration(rand.Int64N(int64(delay)/5 + 1))
		next := supervisor.now().Add(delay)
		supervisor.set(FounderStatus{Phase: phase, Attempt: attempt, LastError: err.Error(), NextRetry: next})
		level := slog.LevelWarn
		if phase == FounderPhaseOperatorAction {
			level = slog.LevelError
		}
		logger.Log(ctx, level, "seed founder attempt failed; embedded NATS stays up",
			"phase", string(phase), "attempt", attempt, "retry_in", delay.Round(time.Second), "error", err)
		backoff = min(backoff*2, maximum)
		select {
		case <-ctx.Done():
			supervisor.set(FounderStatus{Phase: FounderPhaseStopped, Attempt: attempt, LastError: err.Error()})
			return false
		case <-after(delay):
		}
	}
}

func testAuthenticatedOperatorToHostDeliveryWithControllerLoss(t *testing.T, production, blackhole, forceRestart bool) {
	tier.Integration(t)
