		DeploymentID: "0000000000EKZ0YK71TYZK31W5", Cell: "lab", Environment: "test"})
	profile := WorkloadProfile{Resources: placement.Resources{CPU: 1, MemoryBytes: 64 << 20, DiskBytes: 128 << 20}}
	auth := newAuthenticatedNATS(t, "lab", "peer0", "peer1", "peer2")
	controllerPublic, _ := testEd25519(t, root, "controller.key")
	operatorPublic, _ := testEd25519(t, root, "operator.key")
	hostPublic, hostPrivate := testEd25519(t, root, "host.key")
	controllerSeeds := make([]string, 3)
	for index := range controllerSeeds {
		_, seed := testNKey(t)
		controllerSeeds[index] = seed
	}
	_, operatorSeed := testNKey(t)
	hostNKey, hostSeed := testNKey(t)
	const peers = 3
	ports := reserveControllerPorts(t, 2*peers)
	clientPorts, routePorts := ports[:peers], ports[peers:]
	routes := make([]string, 3)
	urls := make([]string, 3)
	for index := range routes {
		routes[index] = fmt.Sprintf("nats-route://127.0.0.1:%d", routePorts[index])
		urls[index] = fmt.Sprintf("tls://127.0.0.1:%d", clientPorts[index])
	}
	grant := TrustedSignerConfig{Actor: "ops", PublicKey: base64.StdEncoding.EncodeToString(operatorPublic),
		Roles: []string{"terrabase"}, Environments: []string{"test"}, CanRegisterHosts: true}
	configs := make([]string, 3)
	for index := range configs {
		instance := fmt.Sprintf("peer%d", index)
		configs[index] = testJSONFile(t, root, instance+".json", Config{Version: ConfigVersion,
			NATS: auth.config(t, natscell.Config{Cell: "lab", Instance: instance, Replicas: 3,
				NKeySeedFile: controllerSeeds[index], Embedded: &natscell.Embedded{
					Host: "127.0.0.1", Port: clientPorts[index], RouteHost: "127.0.0.1", RoutePort: routePorts[index],
					Routes: natscell.PeerRoutes(routes, routes[index]), StoreDir: filepath.Join(root, instance), StoreMaxBytes: 4 << 30}}),
			Controller: ControllerConfig{BrokerTicketKeyFile: auth.ticketPrivateFile, CandidateID: entityid.Derive("test-controller", instance), ResponseKeyFile: filepath.Join(root, "controller.key"),
				SpecTrust:             specKeys.config(),
				ArtifactStoreMaxBytes: 64 << 20, TrustedSigners: []TrustedSignerConfig{grant},
				Workloads: map[string]WorkloadProfile{"terrabase": profile}},
		})
	}
	children := make([]*controllerChild, 3)
	for index := range children {
		children[index] = startControllerChild(t, controllerCtx, root, configs[index], 1, index)
	}
	t.Cleanup(func() {
		if !t.Failed() {
			return
		}
		logDir, err := os.MkdirTemp("", "ts-orch-r3-host-caller-logs-")
		if err != nil {
			t.Logf("preserve controller logs: %v", err)
			return
		}
		for index, child := range children {
			data, err := os.ReadFile(child.logPath)
			if err != nil {
				t.Logf("read controller %d log: %v", index, err)
				continue
			}
			if err := os.WriteFile(filepath.Join(logDir, fmt.Sprintf("peer%d.log", index)), data, 0o600); err != nil {
				t.Logf("preserve controller %d log: %v", index, err)
			}
			// The CI runner discards its container filesystem after a failed job.
			// Include the controller stages in the retained test log as well.
			t.Logf("controller peer%d log:\n%s", index, data)
		}
		t.Logf("controller logs: %s", logDir)
	})
	for _, child := range children {
		waitControllerChildReady(t, controllerCtx, child)
	}
	ctx, cancelScenario := context.WithTimeout(controllerCtx, 165*time.Second)
	defer cancelScenario()
	probe, err := auth.start(t, ctx, natscell.Config{Cell: "lab", Instance: "authority-probe", Replicas: 3,
		URL: strings.Join(urls, ",")})
	if err != nil {
		t.Fatal(err)
	}
	defer probe.Close()
	operatorCfg := Config{Version: ConfigVersion,
		NATS: auth.config(t, natscell.Config{Cell: "lab", Instance: "operator", Replicas: 3, ClientRole: "operator",
			URL: strings.Join(urls, ","), NKeySeedFile: operatorSeed}),
		Controller: ControllerConfig{TrustedSigners: []TrustedSignerConfig{grant}},
		Operator:   OperatorConfig{Actor: "ops", SigningKeyFile: filepath.Join(root, "operator.key")},
	}
	operatorConfig := testJSONFile(t, root, "operator.json", operatorCfg)
	applyNativeTestSpec(t, operatorCfg, probe, specKeys, []cellspec.Service{{Role: "terrabase", Profile: profile}}, 1)
	registration := host.Registration{Cell: "lab", Node: "node-a", Environment: "test", Roles: []string{"terrabase"},
		PublicKey: base64.StdEncoding.EncodeToString(hostPublic), NATSUserPublicKey: hostNKey, Generation: 1,
		Capacity: host.Capacity{CPU: 2, MemoryBytes: 256 << 20, DiskBytes: 512 << 20}}
	registrationPath := testJSONFile(t, root, "registration.json", registration)
	if _, err := callR3Operator(ctx, operatorConfig, "host-register", "--registration", registrationPath); err != nil {
		t.Fatalf("signed host registration: %v", err)
	}
	hostURLs := urls
	var proxies []*r3BlackholeProxy
	if blackhole {
		hostURLs = make([]string, len(urls))
		for index := range urls {
			proxies = append(proxies, newR3BlackholeProxy(t, fmt.Sprintf("127.0.0.1:%d", clientPorts[index])))
			hostURLs[index] = "tls://" + proxies[index].listener.Addr().String()
		}
	}
	hostRuntime, err := auth.start(t, ctx, natscell.Config{Cell: "lab", Instance: "node-a", Replicas: 3,
		URL: strings.Join(hostURLs, ","), NKeySeedFile: hostSeed, ClientRole: "host"})
	if err != nil {
		t.Fatal(err)
	}
	defer hostRuntime.Close()
	hostConn := hostRuntime.Conn()
	if forceRestart {
		// Keep every host connection on the controllable proxies. The normal
		// lab client may learn direct broker URLs from NATS INFO messages.
		options := hostConn.Opts
		options.IgnoreDiscoveredServers = true
		hostConn, err = options.Connect()
		if err != nil {
			t.Fatalf("connect isolated host through proxies: %v", err)
		}
		defer hostConn.Close()
	}
	runner := &inMemoryRunner{}
	clock := &testBrokerClock{}
	clock.healthy.Store(true)
	var agentRunner host.Runner = runner
	var stopRunner *r3TimedStopRunner
	var acceptedSessions r3AcceptedSessionTrace
	if production {
		baseRunner := &r3StopOnCloseRunner{inMemoryRunner: runner}
		agentRunner = baseRunner
		if blackhole {
			stopRunner = &r3TimedStopRunner{r3StopOnCloseRunner: baseRunner}
			agentRunner = stopRunner
			originalLogger := slog.Default()
			slog.SetDefault(slog.New(r3AcceptedSessionHandler{next: slog.NewTextHandler(os.Stderr, nil), sessions: &acceptedSessions}))
			defer slog.SetDefault(originalLogger)
		}
	}
	agentConfig := host.AgentConfig{WorkloadIdentity: testHostWorkloadIdentity(), Cell: "lab", Node: "node-a", Environment: "test", Roles: []string{"terrabase"},
		Conn: hostConn, Identity: hostPrivate, NATSUserPublicKey: hostNKey, ControllerPublicKey: controllerPublic, Runner: agentRunner,
		InstallRoot: testHostInstallRoot(t), StateRoot: testHostStateRoot(t), PollInterval: 100 * time.Millisecond,
		ClockCheck: controllerClockCheck(clock)}
	agent, err := host.NewAgent(agentConfig)
	if err != nil {
		t.Fatal(err)
	}
	agentCtx, stopAgent := context.WithCancel(controllerCtx)
	defer stopAgent()
	agentDone := make(chan error, 1)
	go func() { agentDone <- agent.Run(agentCtx) }()
	firstSession := waitR3HostSession(t, ctx, operatorConfig, agentDone, time.Time{})
	firstDigest := deployR3Workload(t, ctx, root, operatorConfig, runner, 1)
	// Controller readiness does not prove that every host/delivery stream has
	// two current followers. Inject loss only after the whole caller's durable
	// state can survive it, including signed sessions in the control log.
	waitR3CallerStreamQuorum(t, ctx, probe, -1)
	connected := hostConn.ConnectedUrl()
	failedPeer := -1
	for index, url := range hostURLs {
		if connected == url {
			failedPeer = index
			break
		}
	}
	if failedPeer < 0 {
		t.Fatalf("host connected to unexpected NATS URL %q", connected)
	}
	before := waitR3Authority(t, ctx, probe, 0, "")
	t.Logf("crashing peer%d host_url=%s authority=%+v", failedPeer, connected, before)
	if blackhole {
		proxies[failedPeer].blocked.Store(true)
	}
	crashControllerChild(t, children[failedPeer])
	var postCrashExpiry int64
	var postCrashAdvancements uint64
	if blackhole {
		postCrashExpiry, postCrashAdvancements = acceptedSessions.snapshot()
		if postCrashExpiry == 0 {
			t.Fatal("host session trace did not capture the accepted pre-failure session")
		}
	}
	reconnectDeadline := time.NewTimer(15 * time.Second)
	reconnectPoll := time.NewTicker(50 * time.Millisecond)
	defer reconnectDeadline.Stop()
	defer reconnectPoll.Stop()
	for !hostConn.IsConnected() || hostConn.ConnectedUrl() == connected {
		select {
		case err := <-agentDone:
			t.Fatalf("host agent exited before reconnecting away from crashed controller: %v", err)
		case <-reconnectDeadline.C:
			t.Fatalf("host did not reconnect away from crashed controller %q within session headroom; current %q", connected, hostConn.ConnectedUrl())
		case <-ctx.Done():
			t.Fatalf("host reconnect interrupted after controller loss: %v", ctx.Err())
		case <-reconnectPoll.C:
		}
	}
	if production && blackhole {
		var stoppedErr error
		var stopped bool
		if forceRestart {
			// Hide both surviving broker links until the old signed execution
			// reserve expires. This exercises the supervisor restart path even
			// when the controller backend recovers promptly in the lab.
			for index := range proxies {
				if index != failedPeer {
					proxies[index].blocked.Store(true)
				}
			}
			select {
			case stoppedErr = <-agentDone:
				stopped = true
			case <-ctx.Done():
				t.Fatalf("host did not fence while session links were blocked: %v", ctx.Err())
			}
		} else {
			_, stoppedErr, stopped = observeR3HostSession(ctx, operatorConfig, agentDone, firstSession.SessionExpiresAt)
			if stoppedErr == nil {
				stoppedErr, stopped = observeR3HostReconnect(ctx, hostConn, hostURLs, urls, failedPeer,
					&acceptedSessions, postCrashExpiry, postCrashAdvancements, agentDone)
			}
		}
		if stopped {
			// A surviving NATS connection does not prove the JetStream session
			// backend recovered before the old signed lease ran out. This is the
			// host's fail-closed branch, followed by supervised restart.
			assertR3HostFenced(t, ctx, runner, stopRunner, &acceptedSessions, stoppedErr)
			t.Logf("host fenced during controller recovery: %v", stoppedErr)
			oldSession, ok := acceptedSessions.latest()
			if !ok {
				t.Fatal("host did not trace the fenced signed session")
			}
			if forceRestart {
				for index := range proxies {
					if index != failedPeer {
						proxies[index].blocked.Store(false)
					}
				}
			}
			agent, err = host.NewAgent(agentConfig)
			if err != nil {
				t.Fatal(err)
			}
			agentCtx, stopAgent = context.WithCancel(controllerCtx)
			defer stopAgent()
			agentDone = make(chan error, 1)
			go func() { agentDone <- agent.Run(agentCtx) }()
			_ = waitR3RestartedSession(t, ctx, operatorConfig, hostConn, hostURLs, urls, failedPeer,
				&acceptedSessions, oldSession, agentDone)
		} else if stoppedErr != nil {
			t.Fatalf("host recovery observation failed: %v", stoppedErr)
		}
	} else {
		_ = waitR3HostSession(t, ctx, operatorConfig, agentDone, firstSession.SessionExpiresAt, probe)
	}
	for index, child := range children {
		if index != failedPeer {
			assertControllerChildRunning(t, child)
		}
	}
	priorEpoch := uint64(0)
	if before.CandidateID == controllerChildCandidateID(t, children[failedPeer]) {
		priorEpoch = before.Epoch
	}
	after := waitR3Authority(t, ctx, probe, priorEpoch, controllerChildCandidateID(t, children[failedPeer]))
	t.Logf("host_url=%s authority_after=%+v", hostConn.ConnectedUrl(), after)
	operatorProbe, err := auth.start(t, ctx, natscell.Config{Cell: "lab", Instance: "operator-probe", Replicas: 3, ClientRole: "operator",
		URL: strings.Join(urls, ","), NKeySeedFile: operatorSeed})
	if err != nil {
		t.Fatal(err)
	}
	defer operatorProbe.Close()
	secondDigest := deployR3Workload(t, ctx, root, operatorConfig, runner, 2,
		&r3CallerDiagnostics{probe: probe, operatorProbe: operatorProbe, agentDone: agentDone})
	waitR3CallerStreamQuorum(t, ctx, probe, failedPeer)
	if firstDigest == secondDigest {
		t.Fatal("replacement workload did not change artifact digest")
	}
	if production && blackhole {
		lastSession := waitR3HostSession(t, ctx, operatorConfig, agentDone, firstSession.SessionExpiresAt)
		stopRunner.stoppedAt.Store(0)
		for index, child := range children {
			if index != failedPeer {
				crashControllerChild(t, child)
				break
			}
		}
		// Earlier startup, reconnect and restart waits cannot shorten the
		// signed session's remaining execution reserve. Keep the absolute
		// before-expiry assertion in assertR3HostFenced.
		acceptedUntil, _ := acceptedSessions.snapshot()
		fenceDeadline := time.NewTimer(time.Until(time.Unix(0, acceptedUntil)))
		defer fenceDeadline.Stop()
		select {
		case err := <-agentDone:
			assertR3HostFenced(t, controllerCtx, runner, stopRunner, &acceptedSessions, err)
			t.Logf("host fenced before accepted expiry after quorum loss: observed_expiry=%s", lastSession.SessionExpiresAt)
		case <-fenceDeadline.C:
			t.Fatal("host did not fail closed before accepted signed session expiry after quorum loss")
		}
		return
	}
	stopAgent()
	if err := <-agentDone; !errors.Is(err, context.Canceled) {
		t.Fatalf("host agent shutdown: %v", err)
	}
	for index, child := range children {
		if index != failedPeer {
			signalControllerChild(t, child)
		}
	}
	for index, child := range children {
		if index != failedPeer {
			waitControllerChildStopped(t, child)
		}
	}
}

func stubAuthenticatedController(t *testing.T, cfg *Config) {
	t.Helper()
	previousRuntime, previousMarker := controllerRuntimeProduction, controllerMarkerPresent
	previousBaked, previousAdmission := controllerBakedInputsPresent, controllerBootstrapProduction
	previousFounder, previousClock := controllerFounderProduction, controllerBrokerClockProbe
	previousSeed := rolloutSeedSlot
	controllerRuntimeProduction = func(ctx context.Context, cfg Config, _ func() error) (*natscell.Runtime, error) {
		return natscell.Start(ctx, cfg.NATS)
	}
	controllerMarkerPresent = func() (bool, error) { return false, nil }
	controllerBakedInputsPresent = func() (bool, error) { return true, nil }
	controllerBootstrapProduction = func(context.Context, Config) error { return nil }
	controllerFounderProduction = func(context.Context) error { return nil }
	clock := &testBrokerClock{}
	clock.healthy.Store(true)
	controllerBrokerClockProbe = func() brokerauth.ClockProbe { return clock }
	rolloutSeedSlot = func(Config) (string, error) { return cfg.NATS.Instance, nil }
	t.Cleanup(func() {
		controllerRuntimeProduction, controllerMarkerPresent = previousRuntime, previousMarker
		controllerBakedInputsPresent, controllerBootstrapProduction = previousBaked, previousAdmission
		controllerFounderProduction, controllerBrokerClockProbe = previousFounder, previousClock
		rolloutSeedSlot = previousSeed
	})
	newAcceptedSpecTrust(t, cfg)
}

func TestControllerThreeProcessBootstrapAndRestart(t *testing.T) {
	if configPath := os.Getenv("TS_ORCH_TEST_CONTROLLER_CHILD_CONFIG"); configPath != "" {
		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
		defer stop()
		cfg, err := LoadConfig(configPath)
		if err != nil {
			t.Fatal(err)
		}
		stubAuthenticatedController(t, &cfg)
		configPath = testJSONFile(t, t.TempDir(), "controller.json", cfg)
		if err := Run(ctx, []string{"run", "--config", configPath}, os.Stdout); err != nil && ctx.Err() == nil {
			t.Fatal(err)
		}
		return
	}

func startControllerChild(t *testing.T, ctx context.Context, root, config string, boot, index int) *controllerChild {
	t.Helper()
	executable, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	logPath := filepath.Join(root, fmt.Sprintf("boot%d-peer%d.log", boot, index))
	logFile, err := os.Create(logPath)
	if err != nil {
		t.Fatal(err)
	}
	cmd := exec.CommandContext(ctx, executable, "-test.run=^TestControllerThreeProcessBootstrapAndRestart$")
	cmd.Env = append(os.Environ(), "TS_ORCH_TEST_CONTROLLER_CHILD_CONFIG="+config)
	cmd.Stdout, cmd.Stderr = logFile, logFile
	if err := cmd.Start(); err != nil {
		logFile.Close()
		t.Fatal(err)
	}
	child := &controllerChild{cmd: cmd, done: make(chan struct{}), logPath: logPath, started: time.Now()}
	go func() {
		child.err = cmd.Wait()
		logFile.Close()
		close(child.done)
	}()
	t.Cleanup(func() {
		select {
		case <-child.done:
			return
		default:
		}
		_ = cmd.Process.Kill()
		// Reap even failed fixtures before the next lab test starts. Reading
		// Cmd.ProcessState while Wait writes it also races under -race.
		select {
		case <-child.done:
		case <-time.After(controllerStopBudget):
			t.Errorf("controller cleanup did not reap child: %s", child.logPath)
		}
	})
	return child
}

func crashControllerChild(t *testing.T, child *controllerChild) {
	t.Helper()
	if err := child.cmd.Process.Kill(); err != nil {
		t.Fatal(err)
	}
	select {
	case <-child.done:
	case <-time.After(10 * time.Second):
		t.Fatalf("crashed controller did not exit: %s", child.logPath)
	}
}

func newAuthenticatedNATS(t *testing.T, cell string, brokers ...string) *authenticatedNATS {
	t.Helper()
	a := &authenticatedNATS{root: t.TempDir(), cell: cell, brokers: slices.Clone(brokers)}
	a.tls, a.routePassword = testR3TLSMaterial(t, a.root)
	operator, err := nkeys.CreateOperator()
	if err != nil {
		t.Fatal(err)
	}
	system, err := nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	a.account, err = nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	operatorID, _ := operator.PublicKey()
	systemID, _ := system.PublicKey()
	a.cellID, _ = a.account.PublicKey()
	operatorClaim := jwt.NewOperatorClaims(operatorID)
	operatorClaim.SystemAccount = systemID
	operatorJWT, err := operatorClaim.Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	systemJWT, err := jwt.NewAccountClaims(systemID).Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	cellClaim := jwt.NewAccountClaims(a.cellID)
	cellClaim.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: 256 << 20, DiskStorage: 8 << 30, Streams: 100, Consumer: 100}
	a.cellJWT, err = cellClaim.Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	write := func(name, raw string) string {
		path := filepath.Join(a.root, name)
		if err := os.WriteFile(path, []byte(raw), 0o600); err != nil {
			t.Fatal(err)
		}
		return path
	}
	a.operatorFile = write("operator.jwt", operatorJWT)
	a.systemFile = write("system.jwt", systemJWT)
	a.cellFile = write("cell.jwt", a.cellJWT)
	systemUser, systemCredentials := testBrokerJWTUser(t, a.root, "system.creds", system, systemID,
		[]string{"$SYS.REQ.ACCOUNT." + a.cellID + ".CLAIMS.UPDATE"}, nil)
	systemClaim, err := jwt.DecodeUserClaims(testDecoratedJWT(t, systemCredentials))
	if err != nil {
		t.Fatal(err)
	}
	systemClaim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(cell, systemUser) + ".>"}
	a.systemCredentials = testBrokerJWTUserWithClaim(t, a.root, "system.creds", system, systemClaim)
	public, _ := testEd25519(t, a.root, "ticket.key")
	a.ticketPrivateFile = filepath.Join(a.root, "ticket.key")
	a.ticketPublicFile = write("ticket.pub", base64.StdEncoding.EncodeToString(public))
	return a
}

func (a *authenticatedNATS) config(t *testing.T, cfg natscell.Config) natscell.Config {
	t.Helper()
	if cfg.Cell != "" && cfg.Cell != a.cell {
		t.Fatalf("fixture cell %q differs from client cell %q", a.cell, cfg.Cell)
	}
	cfg.Cell = a.cell
	if cfg.Instance == "" {
		cfg.Instance = "one"
	}
	if cfg.Replicas == 0 {
		cfg.Replicas = 1
	}
	role := cfg.ClientRole
	if role == "" {
		role = "controller"
	}
	var user nkeys.KeyPair
	var err error
	if cfg.NKeySeedFile != "" {
		seed, readErr := os.ReadFile(cfg.NKeySeedFile)
		if readErr != nil {
			t.Fatal(readErr)
		}
		user, err = nkeys.FromSeed(seed)
		clear(seed)
	} else if cfg.CredentialsFile != "" {
		credentials, readErr := os.ReadFile(cfg.CredentialsFile)
		if readErr != nil {
			t.Fatal(readErr)
		}
		user, err = nkeys.ParseDecoratedUserNKey(credentials)
		clear(credentials)
	} else {
		user, err = nkeys.CreateUser()
	}
	if err != nil {
		t.Fatal(err)
	}
	defer user.Wipe()
	public, err := user.PublicKey()
	if err != nil {
		t.Fatal(err)
	}
	claim := jwt.NewUserClaims(public)
	claim.IssuerAccount = a.cellID
	claim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(a.cell, public) + ".>"}
	switch role {
	case "controller":
		claim.Pub.Allow = natscell.ControllerPublishes(a.cell)
		claim.Pub.Allow.Add(natscell.GlobalControllerPublishes()...)
		claim.Pub.Allow.Add(natscell.GlobalControllerRequests()...)
		claim.Pub.Allow.Add("$JS.ACK.>")
		claim.Sub.Allow.Add(natscell.ControllerSubscriptions(a.cell)...)
		claim.Sub.Allow.Add(natscell.GlobalControllerRequests()...)
		claim.Sub.Allow.Add(protocol.ObservabilityGrant(a.cell), protocol.Broker(a.cell, "ticket", ">"), protocol.Broker(a.cell, "fence", cfg.Instance))
		claim.Resp = &jwt.ResponsePermission{MaxMsgs: 1, Expires: 5 * time.Second}
	case "operator":
		claim.Pub.Allow = natscell.BrokerOperatorPublishPermissions(a.cell)
	case "host":
		claim.Pub.Allow = jwt.StringList{protocol.AgentObservation(a.cell, public, "*")}
	default:
		t.Fatalf("unsupported authenticated fixture role %q", role)
	}
	cfg.CredentialsFile = testBrokerJWTUserWithKey(t, a.root, cfg.Instance+"-"+public+".creds", a.account, user, claim)
	cfg.NKeySeedFile = ""
	cfg.TLS = a.tls
	cfg.URL = strings.ReplaceAll(cfg.URL, "nats://", "tls://")
	if cfg.Embedded != nil {
		embedded := *cfg.Embedded
		cfg.Embedded = &embedded
		embedded.Users = nil
		embedded.TLS, embedded.RouteTLS = a.tls, a.tls
		embedded.RouteUser, embedded.RoutePasswordFile = "integration-route", a.routePassword
		embedded.OperatorJWTFile, embedded.SystemJWTFile, embedded.CellJWTFile = a.operatorFile, a.systemFile, a.cellFile
		embedded.SystemCredentialsFile, embedded.TicketPublicKeyFile = a.systemCredentials, a.ticketPublicFile
		embedded.BrokerIDs = slices.Clone(a.brokers)
		if len(embedded.BrokerIDs) == 0 {
			embedded.BrokerIDs = []string{cfg.Instance}
		}
		if embedded.StoreDir == "" {
			embedded.StoreDir = filepath.Join(a.root, cfg.Instance)
		}
		if embedded.Host == "" {
			embedded.Host = "127.0.0.1"
		}
		if embedded.Port == 0 {
			embedded.Port = reserveControllerPort(t)
		}
	}
	return cfg
}

func (a *authenticatedNATS) start(t *testing.T, ctx context.Context, cfg natscell.Config) (*natscell.Runtime, error) {
	t.Helper()
	runtime, err := natscell.Start(ctx, a.config(t, cfg))
	if err != nil {
		return nil, err
	}
	t.Cleanup(func() { _ = runtime.Close() })
	if cfg.Embedded != nil {
		if err := runtime.ApplyCellClaim(ctx, 1, a.cellJWT); err != nil {
			return nil, fmt.Errorf("apply fixture claim: %w", err)
		}
		if err := runtime.Bridge().OpenUntil(1, a.cellJWT, time.Now().Add(5*time.Minute)); err != nil {
			return nil, fmt.Errorf("open fixture bridge: %w", err)
		}
	}
	return runtime, nil
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

func (*inMemoryRunner) Recover(context.Context) error { return nil }
func (r *inMemoryRunner) Apply(_ context.Context, workload host.Workload) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.observed = host.Observation{Role: workload.Role, Digest: workload.Digest, Fingerprint: workload.Fingerprint, Running: true, PID: 1}
	return nil
}
func (r *inMemoryRunner) Stop(_ context.Context, role string) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.observed = host.Observation{Role: role}
	return nil
}
func (r *inMemoryRunner) Observe(_ context.Context, _ string) (host.Observation, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.observed, nil
}
func (*inMemoryRunner) Close(context.Context) error { return nil }

func (r *r3StopOnCloseRunner) Close(ctx context.Context) error {
	return r.Stop(ctx, "terrabase")
}

func newR3BlackholeProxy(t *testing.T, target string) *r3BlackholeProxy {
	t.Helper()
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	proxy := &r3BlackholeProxy{listener: listener, release: make(chan struct{})}
	t.Cleanup(func() {
		_ = listener.Close()
		close(proxy.release)
		proxy.mu.Lock()
		defer proxy.mu.Unlock()
		for _, conn := range proxy.conns {
			_ = conn.Close()
		}
	})
	go func() {
		for {
			client, err := listener.Accept()
			if err != nil {
				return
			}
			upstream, err := net.DialTimeout("tcp", target, time.Second)
			if err != nil {
				_ = client.Close()
				continue
			}
			proxy.mu.Lock()
			proxy.conns = append(proxy.conns, client, upstream)
			proxy.mu.Unlock()
			go proxy.forward(client, upstream)
			go proxy.forward(upstream, client)
		}
	}()
	return proxy
}

func (p *r3BlackholeProxy) forward(source, destination net.Conn) {
	defer source.Close()
	defer destination.Close()
	var buffer [4096]byte
	for {
		count, err := source.Read(buffer[:])
		if err != nil {
			if p.blocked.Load() {
				<-p.release
			}
			return
		}
		if !p.blocked.Load() {
			if _, err := destination.Write(buffer[:count]); err != nil {
				if p.blocked.Load() {
					<-p.release
				}
				return
			}
		}
	}
}

func (r *r3TimedStopRunner) Close(ctx context.Context) error {
	err := r.r3StopOnCloseRunner.Close(ctx)
	if err == nil {
		r.stoppedAt.CompareAndSwap(0, time.Now().UnixNano())
	}
	return err
}

func (h r3AcceptedSessionHandler) Handle(ctx context.Context, record slog.Record) error {
	if record.Message == "host session accepted" {
		var event r3AcceptedSessionEvent
		record.Attrs(func(attr slog.Attr) bool {
			switch attr.Key {
			case "phase":
				event.phase = attr.Value.String()
			case "session_id_hash":
				event.sessionIDHash = attr.Value.String()
			case "expires_at":
				event.expiresAt, _ = time.Parse(time.RFC3339Nano, attr.Value.String())
			}
			return true
		})
		if event.phase != "" && event.sessionIDHash != "" && !event.expiresAt.IsZero() {
			h.sessions.record(event)
		}
	}
	return h.next.Handle(ctx, record)
}

func waitR3Authority(t *testing.T, ctx context.Context, probe *natscell.Runtime, priorEpoch uint64, failedCandidate string) authority.Snapshot {
	t.Helper()
	checkCtx, cancel := context.WithTimeout(ctx, 35*time.Second)
	defer cancel()
	var last authority.Snapshot
	var lastErr error
	for checkCtx.Err() == nil {
		attempt, stop := context.WithTimeout(checkCtx, 2*time.Second)
		last, lastErr = authority.Observe(attempt, probe.JetStream(), "lab")
		stop()
		if lastErr == nil && last.Ready && last.Epoch > priorEpoch && last.ExpiresAt.After(time.Now().Add(5*time.Second)) &&
			last.CandidateID != failedCandidate {
			return last
		}
		select {
		case <-checkCtx.Done():
		case <-time.After(250 * time.Millisecond):
		}
	}
	t.Fatalf("authority not ready after candidate %s loss: prior epoch=%d last=%+v err=%v probe_url=%s: %v",
		failedCandidate, priorEpoch, last, lastErr, probe.Conn().ConnectedUrl(), checkCtx.Err())
	return authority.Snapshot{}
}

func waitR3CallerStreamQuorum(t *testing.T, ctx context.Context, probe *natscell.Runtime, failedPeer int) {
	t.Helper()
	started := time.Now()
	checkCtx, cancel := context.WithTimeout(ctx, 25*time.Second)
	defer cancel()
	streams := []string{authority.ControlStreamName, delivery.IntentStream,
		"OBJ_" + delivery.ArtifactBucket, "KV_" + delivery.AdmissionBucket,
		"KV_" + delivery.OperationBucket, "KV_TS_HOST_STATE"}
	var lastStream string
	var lastCluster *jetstream.ClusterInfo
	var lastErr error
	for checkCtx.Err() == nil {
		quorate := true
		for _, name := range streams {
			attempt, stop := context.WithTimeout(checkCtx, 2*time.Second)
			stream, err := probe.JetStream().Stream(attempt, name)
			var info *jetstream.StreamInfo
			if err == nil {
				info, err = stream.Info(attempt)
			}
			stop()
			if err != nil || !r3CallerStreamQuorate(info, failedPeer) {
				lastStream, lastErr, lastCluster = name, err, nil
				if info != nil {
					lastCluster = info.Cluster
				}
				quorate = false
				break
			}
		}
		if quorate {
			t.Logf("all %d caller streams have a current quorum after peer%d loss: wait=%s", len(streams), failedPeer, time.Since(started))
			return
		}
		select {
		case <-checkCtx.Done():
		case <-time.After(250 * time.Millisecond):
		}
	}
	t.Fatalf("caller stream %s lacks a current surviving quorum after peer%d loss: cluster=%+v err=%v: %v",
		lastStream, failedPeer, lastCluster, lastErr, checkCtx.Err())
}

func r3CallerStreamQuorate(info *jetstream.StreamInfo, failedPeer int) bool {
	if info == nil || info.Config.Replicas != 3 || info.Cluster == nil ||
		info.Cluster.Leader == "" || len(info.Cluster.Replicas) != 2 {
		return false
	}
	failedName := fmt.Sprintf("lab-peer%d", failedPeer)
	if info.Cluster.Leader == failedName {
		return false
	}
	current := map[string]bool{info.Cluster.Leader: true}
	for _, peer := range info.Cluster.Replicas {
		if peer == nil || current[peer.Name] {
			return false
		}
		if peer.Name != failedName {
			current[peer.Name] = peer.Current && !peer.Offline && !peer.Pending
		}
	}
	for index := range 3 {
		name := fmt.Sprintf("lab-peer%d", index)
		if index == failedPeer {
			continue
		}
		if !current[name] {
			return false
		}
	}
	return true
}

func callR3Operator(ctx context.Context, config, operation string, args ...string) ([]byte, error) {
	var output bytes.Buffer
	command := append([]string{"operator", operation, "--config", config}, args...)
	err := Run(ctx, command, &output)
	return output.Bytes(), err
}

func observeR3HostSession(ctx context.Context, config string, agentDone <-chan error, after time.Time) (host.HostStatus, error, bool) {
	var lastErr error
	for ctx.Err() == nil {
		attempt, stop := context.WithTimeout(ctx, 8*time.Second)
		data, err := callR3Operator(attempt, config, "hosts")
		stop()
		if err == nil {
			var statuses []host.HostStatus
			err = json.Unmarshal(data, &statuses)
			if err == nil && len(statuses) == 1 && statuses[0].SessionExpiresAt.After(after) &&
				statuses[0].SessionExpiresAt.After(time.Now().Add(5*time.Second)) {
				select {
				case agentErr := <-agentDone:
					return host.HostStatus{}, agentErr, true
				default:
				}
				return statuses[0], nil, false
			}
		}
		lastErr = err
		select {
		case agentErr := <-agentDone:
			return host.HostStatus{}, agentErr, true
		case <-ctx.Done():
		case <-time.After(150 * time.Millisecond):
		}
	}
	return host.HostStatus{}, fmt.Errorf("%w; last error %v", ctx.Err(), lastErr), false
}

func waitR3RestartedSession(t *testing.T, ctx context.Context, config string, conn *nats.Conn,
	hostURLs, urls []string, failedPeer int, acceptedSessions *r3AcceptedSessionTrace,
	oldSession r3AcceptedSessionEvent, agentDone <-chan error) host.HostStatus {
	t.Helper()
	var lastStatus host.HostStatus
	var lastErr error
	for ctx.Err() == nil {
		var acquired, renewed r3AcceptedSessionEvent
		for _, event := range acceptedSessions.eventsAfter(oldSession.sequence) {
			if event.phase == "acquire" && event.sessionIDHash != oldSession.sessionIDHash {
				acquired = event
				renewed = r3AcceptedSessionEvent{}
			}
			if acquired.sequence != 0 && event.phase == "renew" &&
				event.sequence > acquired.sequence && event.sessionIDHash == acquired.sessionIDHash &&
				event.expiresAt.After(acquired.expiresAt) && event.expiresAt.After(time.Now().Add(5*time.Second)) {
				renewed = event
			}
		}
		if renewed.sequence != 0 && conn.IsConnected() &&
			r3ConnectedToSurvivor(conn.ConnectedUrl(), hostURLs, urls, failedPeer) {
			attempt, stop := context.WithTimeout(ctx, 2*time.Second)
			data, err := callR3Operator(attempt, config, "hosts")
			stop()
			if err == nil {
				var statuses []host.HostStatus
				err = json.Unmarshal(data, &statuses)
				if err == nil && len(statuses) == 1 {
					lastStatus = statuses[0]
					if !lastStatus.SessionExpiresAt.Before(renewed.expiresAt) &&
						lastStatus.SessionExpiresAt.After(time.Now().Add(5*time.Second)) {
						select {
						case agentErr := <-agentDone:
							t.Fatalf("restarted host agent exited after signed acquire and renew: %v", agentErr)
						default:
						}
						t.Logf("restarted host accepted fresh signed session: old_hash=%s new_hash=%s acquire_expiry=%s renew_expiry=%s status_expiry=%s",
							oldSession.sessionIDHash, acquired.sessionIDHash, acquired.expiresAt, renewed.expiresAt, lastStatus.SessionExpiresAt)
						return lastStatus
					}
				}
			}
			lastErr = err
		}
		select {
		case agentErr := <-agentDone:
			t.Fatalf("restarted host agent exited before fresh signed acquire and renew: %v", agentErr)
		case <-ctx.Done():
		case <-time.After(150 * time.Millisecond):
		}
	}
	t.Fatalf("restarted host did not accept a distinct signed acquisition and renewal on a surviving endpoint: old_hash=%s status_expiry=%s last_error=%v: %v",
		oldSession.sessionIDHash, lastStatus.SessionExpiresAt, lastErr, ctx.Err())
	return host.HostStatus{}
}

func assertR3HostFenced(t *testing.T, ctx context.Context, runner *inMemoryRunner, stopRunner *r3TimedStopRunner,
	acceptedSessions *r3AcceptedSessionTrace, err error) {
	t.Helper()
	if err == nil || errors.Is(err, context.Canceled) {
		t.Fatalf("host did not fail closed on session loss: %v", err)
	}
	if !strings.Contains(err.Error(), "host session execution reserve exhausted") {
		t.Fatalf("host stopped for a reason other than signed lease reserve: %v", err)
	}
	stoppedAt := stopRunner.stoppedAt.Load()
	acceptedUntil, _ := acceptedSessions.snapshot()
	if stoppedAt == 0 || acceptedUntil == 0 || !time.Unix(0, stoppedAt).Before(time.Unix(0, acceptedUntil)) {
		t.Fatalf("host workload stop missed accepted signed expiry: stopped_at=%s accepted_expiry=%s err=%v",
			time.Unix(0, stoppedAt), time.Unix(0, acceptedUntil), err)
	}
	observed, observeErr := runner.Observe(ctx, "terrabase")
	if observeErr != nil || observed.Running {
		t.Fatalf("host retained workload after session loss: observed=%+v err=%v", observed, observeErr)
	}
}

func observeR3HostReconnect(ctx context.Context, conn *nats.Conn, hostURLs, urls []string,
	failedPeer int, acceptedSessions *r3AcceptedSessionTrace, priorExpiry int64, priorAdvancements uint64,
	agentDone <-chan error) (error, bool) {
	if priorExpiry == 0 {
		return errors.New("host session trace did not capture the accepted pre-failure session"), false
	}
	for ctx.Err() == nil {
		connectedToSurvivor := conn.IsConnected() && r3ConnectedToSurvivor(conn.ConnectedUrl(), hostURLs, urls, failedPeer)
		currentExpiry, currentAdvancements := acceptedSessions.snapshot()
		if connectedToSurvivor && currentAdvancements >= priorAdvancements+2 &&
			time.Unix(0, currentExpiry).After(time.Now().Add(5*time.Second)) {
			select {
			case err := <-agentDone:
				return err, true
			default:
			}
			return nil, false
		}
		select {
		case err := <-agentDone:
			return err, true
		case <-ctx.Done():
		case <-time.After(100 * time.Millisecond):
		}
	}
	currentExpiry, currentAdvancements := acceptedSessions.snapshot()
	return fmt.Errorf("host did not reconnect to a surviving controller and accept renewed valid sessions: connected_to_survivor=%t prior_expiry=%s current_expiry=%s prior_advancements=%d current_advancements=%d: %w",
		conn.IsConnected() && r3ConnectedToSurvivor(conn.ConnectedUrl(), hostURLs, urls, failedPeer),
		time.Unix(0, priorExpiry).Format(time.RFC3339Nano), time.Unix(0, currentExpiry).Format(time.RFC3339Nano),
		priorAdvancements, currentAdvancements, ctx.Err()), false
}

func r3ConnectedToSurvivor(currentURL string, hostURLs, urls []string, failedPeer int) bool {
	currentEndpoint, ok := r3NATSEndpointHostPort(currentURL)
	if !ok {
		return false
	}
	for index := range urls {
		if index == failedPeer {
			continue
		}
		if index < len(hostURLs) {
			if hostEndpoint, valid := r3NATSEndpointHostPort(hostURLs[index]); valid && currentEndpoint == hostEndpoint {
				return true
			}
		}
		if brokerEndpoint, valid := r3NATSEndpointHostPort(urls[index]); valid && currentEndpoint == brokerEndpoint {
			return true
		}
	}
	return false
}

func r3NATSEndpointHostPort(rawURL string) (string, bool) {
	parsed, err := url.Parse(rawURL)
	if err != nil || (parsed.Scheme != "nats" && parsed.Scheme != "tls") ||
		parsed.User != nil || parsed.Hostname() == "" || parsed.Port() == "" ||
		parsed.Path != "" || parsed.RawQuery != "" || parsed.ForceQuery || parsed.Fragment != "" {
		return "", false
	}
	return parsed.Host, true
}

func deployR3Workload(t *testing.T, ctx context.Context, root, config string, runner *inMemoryRunner, generation uint64, diagnostics ...*r3CallerDiagnostics) string {
	t.Helper()
	path := filepath.Join(root, fmt.Sprintf("workload-%d", generation))
	if err := os.WriteFile(path, []byte(fmt.Sprintf("#!/bin/sh\n# generation %d\nsleep 30\n", generation)), 0o755); err != nil {
		t.Fatal(err)
	}
	source := delivery.ArtifactSource{Repository: "https://example.com/terrascale/r3-caller",
		Commit: strings.Repeat("a", 40), TreeDigest: strings.Repeat("b", 64)}
	var stopAdmissionMonitor chan struct{}
	var admissionMonitorDone chan struct{}
	if len(diagnostics) != 0 {
		stopAdmissionMonitor = make(chan struct{})
		admissionMonitorDone = make(chan struct{})
		go func() {
			defer close(admissionMonitorDone)
			ticker := time.NewTicker(15 * time.Second)
			defer ticker.Stop()
			for {
				select {
				case <-stopAdmissionMonitor:
					return
				case <-ticker.C:
					logR3AdmissionState(t, t.Context(), diagnostics[0].probe, diagnostics[0].operatorProbe)
				}
			}
		}()
	}
	pushStarted := time.Now()
	data, err := callR3Operator(ctx, config, "artifact-push", "--file", path,
		"--repository", source.Repository, "--commit", source.Commit, "--tree-digest", source.TreeDigest,
		"--role", "terrabase", "--environment", "test")
	if stopAdmissionMonitor != nil {
		close(stopAdmissionMonitor)
		<-admissionMonitorDone
		t.Logf("generation-%d artifact push elapsed=%s error=%v", generation, time.Since(pushStarted), err)
	}
	if err != nil {
		if len(diagnostics) != 0 {
			logR3AdmissionState(t, t.Context(), diagnostics[0].probe, diagnostics[0].operatorProbe)
		}
		t.Fatalf("push artifact generation %d: %v", generation, err)
	}
	var record delivery.ArtifactRecord
	if err := json.Unmarshal(data, &record); err != nil {
		t.Fatal(err)
	}
	intent := delivery.Intent{SchemaVersion: delivery.SchemaVersion,
		OperationID: entityid.Derive("test-workload", fmt.Sprint(generation)), Source: source,
		ArtifactDigest: record.Digest, ManifestDigest: record.ManifestDigest,
		Cell: "lab", Role: "terrabase", Environment: "test", Generation: generation,
		DesiredReplicas: 1, ConfigDigest: delivery.ConfigDigestOf(nil, nil, nil)}
	intentPath := testJSONFile(t, root, fmt.Sprintf("intent-%d.json", generation), intent)
	data, err = callR3Operator(ctx, config, "deploy", "--intent", intentPath)
	if err != nil {
		if len(diagnostics) != 0 {
			logR3AdmissionState(t, t.Context(), diagnostics[0].probe, diagnostics[0].operatorProbe)
		}
		t.Fatalf("submit workload generation %d: %v", generation, err)
	}
	var submitted struct {
		OperationID string `json:"operationId"`
		Fingerprint string `json:"fingerprint"`
	}
	if err := json.Unmarshal(data, &submitted); err != nil || submitted.OperationID == "" || submitted.Fingerprint == "" {
		t.Fatalf("invalid submit receipt: %v: %s", err, data)
	}
	var lastStatus string
	for ctx.Err() == nil {
		attempt, stop := context.WithTimeout(ctx, 8*time.Second)
		data, err := callR3Operator(attempt, config, "status", "--operation-id", submitted.OperationID,
			"--fingerprint", submitted.Fingerprint)
		stop()
		if err == nil {
			var receipt delivery.Receipt
			err = json.Unmarshal(data, &receipt)
			if err == nil {
				lastStatus = receipt.Status
				if receipt.Status == "accepted" {
					break
				}
				if receipt.Status == "rejected" || receipt.Status == "held" {
					t.Fatalf("workload generation %d became %s: %s", generation, receipt.Status, receipt.Error)
				}
			}
		}
		select {
		case <-ctx.Done():
		case <-time.After(150 * time.Millisecond):
		}
	}
	if err := ctx.Err(); err != nil {
		t.Fatalf("workload generation %d not accepted: %v; last status %s", generation, err, lastStatus)
	}
	nextDiagnostic := time.Now().Add(15 * time.Second)
	for ctx.Err() == nil {
		observed, _ := runner.Observe(ctx, "terrabase")
		if observed.Running && observed.Digest == record.Digest {
			return record.Digest
		}
		if len(diagnostics) != 0 {
			select {
			case agentErr := <-diagnostics[0].agentDone:
				logR3CallerState(t, ctx, config, runner, diagnostics[0].probe)
				t.Fatalf("host agent exited before workload generation %d applied: %v", generation, agentErr)
			default:
			}
			if !time.Now().Before(nextDiagnostic) {
				logR3CallerState(t, ctx, config, runner, diagnostics[0].probe)
				nextDiagnostic = time.Now().Add(15 * time.Second)
			}
		}
		select {
		case <-ctx.Done():
		case <-time.After(150 * time.Millisecond):
		}
	}
	t.Fatalf("host did not apply workload generation %d: %v", generation, ctx.Err())
	return ""
}

func (a *Agent) Run(ctx context.Context) error {
	if err := a.runner.Recover(ctx); err != nil {
		return fmt.Errorf("recover native workloads: %w", err)
	}
	work, cancel := context.WithCancel(ctx)
	defer cancel()
	defer func() {
		stopCtx, stopCancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer stopCancel()
		_ = a.runner.Close(stopCtx)
	}()
	defer a.stopAllManagedNativeRoots()
	if err := a.checkClock(); err != nil {
		return err
	}
	if a.cfg.Initialized != nil {
		a.cfg.Initialized()
	}
	if err := a.waitForSession(work); err != nil {
		return err
	}
	lost := make(chan error, 1)
	go a.maintainSession(work, cancel, lost)
	if a.cfg.ManagedRuntimeRoot != "" {
		go a.refreshNativeRootPins(work)
	}
	go a.publishLoad(work)
	go a.publishLogs(work)
	if a.cfg.FollowRollouts != nil {
		go a.cfg.FollowRollouts(work, a)
	}
	if a.cfg.FollowNetBird != nil {
		go a.cfg.FollowNetBird(work, a)
	}
	ticker := time.NewTicker(a.cfg.PollInterval)
	defer ticker.Stop()
	type roleFailure struct {
		class string
		at    time.Time
	}
	failures := make(map[string]roleFailure)
	for {
		ctx := observability.StartTrace(ctx)
		for _, role := range a.cfg.Roles {
			if err := work.Err(); err != nil {
				break
			}
			if a.sessionLost.Load() {
				break
			}
			err := a.reconcile(work, role)
			if a.cfg.ManagedRuntimeRoot == "" || work.Err() != nil || a.sessionLost.Load() {
				continue
			}
			if err == nil {
				if _, failed := failures[role]; failed {
					slog.InfoContext(ctx, "managed host reconciliation recovered", "role", role)
					delete(failures, role)
				}
				continue
			}
			class := managedReconcileErrorClass(err)
			previous := failures[role]
			if class != previous.class || time.Since(previous.at) >= 10*time.Second {
				// A repeated cause is still logged, but only at DEBUG.
				level := slog.LevelDebug
				if class != previous.class {
					level = slog.LevelWarn
				}
				slog.Log(ctx, level, "managed host reconciliation deferred", "role", role, "cause_class", class)
				failures[role] = roleFailure{class: class, at: time.Now()}
			}
		}
		select {
		case err := <-lost:
			return err
		case <-ctx.Done():
			return ctx.Err()
		case <-work.Done():
			if a.sessionLost.Load() {
				// Session loss cancels work before workload shutdown finishes.
				// Wait for its reason so a supervisor sees a failed host.
				return <-lost
			}
			return work.Err()
		case <-ticker.C:
		}
	}
}

func (a *Agent) sendToLeader(ctx context.Context, operation string, payload, out any,
	signedOut *protocol.Envelope, prepare func(*request) error,
) (request, error) {
	for attempt := 1; ; attempt++ {
		r, err := a.makeRequest(operation, payload)
		if err != nil {
			return request{}, err
		}
		if prepare != nil {
			if err := prepare(&r); err != nil {
				return request{}, err
			}
		}
		err = exchangeWithEnvelope(ctx, a.cfg.Conn, a.cfg.Cell, a.cfg.ControllerPublicKey, r, out, signedOut)
		if !errors.Is(err, errControllerNotLeader) || attempt == leaderRequestAttempts {
			return r, err
		}
		select {
		case <-ctx.Done():
			return request{}, ctx.Err()
		case <-time.After(time.Duration(attempt) * leaderRetryBackoff):
		}
	}
}

func (a *Agent) acquire(ctx context.Context) error {
	if err := a.checkClock(); err != nil {
		return err
	}
	var s session
	if _, err := a.sendToLeader(ctx, "session", struct {
		Kind string `json:"kind"`
	}{"acquire"}, &s, nil, func(r *request) error {
		r.Epoch = 0
		return signRequest(r, a.cfg.Identity, a.cfg.Cell)
	}); err != nil {
		return fmt.Errorf("acquire host session: %w", err)
	}
	if s.SessionID != a.processID || s.Epoch == 0 {
		return errors.New("invalid acquired host session")
	}
	if err := a.acceptSession(s); err != nil {
		return err
	}
	a.logSessionAccepted("acquire", s)
	return nil
}

func exchangeWithEnvelope(ctx context.Context, conn *nats.Conn, cell string, controllerKey ed25519.PublicKey,
	r request, out any, signedOut *protocol.Envelope,
) error {
	if conn == nil {
		return errors.New("NATS connection is required")
	}
	data, err := protocol.EncodeJSON(r.Envelope)
	if err != nil {
		return err
	}
	if len(data) > 64<<10 {
		return errors.New("host request is too large")
	}
	subject, err := protocol.AgentObservationSubject(cell, r.NATSUserPublicKey, r.Operation)
	if err != nil {
		return err
	}
	timeout := 5 * time.Second
	if r.Operation == "material" || r.Operation == "function-material" || r.Operation == "volume-init" || r.Operation == "runtime-effect" || r.Operation == "container-material" || r.Operation == "registry-admission" {
		timeout = 30 * time.Second
	}
	deadline, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	msg, err := conn.RequestMsgWithContext(deadline, &nats.Msg{Subject: subject, Data: data, Header: observability.TraceHeader(ctx, nil)})
	if err != nil {
		return err
	}
	if len(msg.Data) > 512<<10 {
		return errors.New("host response is too large")
	}
	var signed protocol.Envelope
	if err := protocol.DecodeStrict(msg.Data, &signed, 512<<10); err != nil {
		return err
	}
	if err := protocol.VerifyEnvelope(signed, protocol.EnvelopeScope{Region: cell, Kind: "host.response." + r.Operation, Actor: "controller", OperationID: entityid.Derive("host-request", r.Nonce), Epoch: r.Epoch}, controllerKey, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: requestTTL, ClockSkew: maxClockSkew}); err != nil {
		return err
	}
	var result response
	if err := decodeStrict([]byte(signed.Payload), &result); err != nil {
		return err
	}
	if result.Nonce != r.Nonce || result.Node != r.Node || result.SessionID != r.SessionID || result.Epoch != r.Epoch || result.Operation != r.Operation {
		return errors.New("host response binding mismatch")
	}
	if result.Error != "" {
		if strings.HasPrefix(result.Error, authority.ErrNotLeader.Error()) {
			return fmt.Errorf("%w: %s", errControllerNotLeader, result.Error)
		}
		if result.Retryable {
			if result.Error == errSessionContention.Error() {
				return errSessionContention
			}
			if r.Operation == "session" {
				return fmt.Errorf("%w: %s", errSessionBackendUnavailable, result.Error)
			}
			return errArtifactPreparing
		}
		if r.Operation == "session" {
			if result.Error == errSessionOwned.Error() {
				return errSessionOwned
			}
			return fmt.Errorf("%w: %s", errSessionRequestDenied, result.Error)
		}
		return fmt.Errorf("host request denied: %s", result.Error)
	}
	if out != nil {
		if err := decodeStrict(result.Payload, out); err != nil {
			return err
		}
	}
	if signedOut != nil {
		*signedOut = signed
	}
	return nil
}

func (a *Agent) maintainSessionLease(ctx context.Context, fail func(error)) {
	watchCtx, stopWatch := context.WithCancel(ctx)
	watchDone := make(chan struct{})
	go func() {
		defer close(watchDone)
		ticks := a.watchdogTicks
		if ticks == nil {
			ticker := time.NewTicker(time.Second)
			defer ticker.Stop()
			ticks = ticker.C
		}
		for {
			select {
			case <-watchCtx.Done():
				return
			case <-ticks:
				if _, _, err := a.executionLease(); err != nil {
					fail(err)
					return
				}
			}
		}
	}()
	defer func() {
		stopWatch()
		<-watchDone
	}()
	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()
	for {
		ctx := observability.StartTrace(ctx)
		current, deadline, err := a.executionLease()
		if err != nil {
			fail(err)
			return
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
		current, deadline, err = a.executionLease()
		if err != nil {
			fail(err)
			return
		}
		var next session
		renewCtx, renewCancel := context.WithDeadline(ctx, deadline)
		_, err = a.sendToLeader(renewCtx, "session", struct {
			Kind string `json:"kind"`
		}{"renew"}, &next, nil, nil)
		renewCancel()
		if err == nil {
			if next.SessionID != current.SessionID || next.Epoch != current.Epoch || !next.ExpiresAt.After(current.ExpiresAt) {
				err = errors.New("renewed session binding mismatch")
			} else if _, _, err = a.executionLease(); err == nil {
				if err = a.acceptSession(next); err == nil {
					a.logSessionAccepted("renew", next)
				}
			}
		}
		_, _, leaseErr := a.executionLease()
		if leaseErr != nil {
			fail(leaseErr)
			return
		}
		if err != nil && retrySessionExchange(err) {
			a.logSessionFailure("renew", err, time.Until(deadline))
			continue
		}
		if err != nil {
			a.logSessionFailure("renew", err, time.Until(deadline))
			fail(fmt.Errorf("host session renewal failed: %w", err))
			return
		}
		a.sessionRecovered()
	}
}

func (a *Agent) stopForLostSession(cancel context.CancelFunc, lost chan<- error, reason error) {
	a.sessionLost.Store(true)
	cancel()
	if err := a.stopAllManagedNativeRoots(); err != nil {
		reason = errors.Join(reason, err)
	}
	a.mu.RLock()
	accepted := a.session
	a.mu.RUnlock()
	if accepted.SessionID != "" && accepted.Epoch != 0 {
		cause := "renewal_failed"
		if errors.Is(reason, errSessionExecutionReserve) {
			cause = "reserve_exhausted"
		}
		digest := sha256.Sum256([]byte(accepted.SessionID))
		slog.Info("host session fenced", "session_id_hash", hex.EncodeToString(digest[:16]),
			"epoch", accepted.Epoch, "expires_at", accepted.ExpiresAt.UTC().Format(time.RFC3339Nano),
			"cause_class", cause)
	}
	stopCtx, stopCancel := context.WithTimeout(context.Background(), sessionExecutionReserve-time.Second)
	if err := a.runner.Close(stopCtx); err != nil {
		reason = errors.Join(reason, fmt.Errorf("stop native workloads after session loss: %w", err))
	}
	stopCancel()
	lost <- reason
}

			pending.query.Succeeded = false
			pending.outcomeReady = true
			a.pending[role] = pending
			if ctx.Err() != nil || a.sessionLost.Load() {
				return
			}
			finishCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
			defer cancel()
			_ = a.flushCycle(finishCtx, role)
		}
	}()
	executable, err := a.fetchArtifact(ctx, role, d.Digest)
	if err != nil {
		return err
	}
	workload := Workload{Role: role, Digest: d.Digest, Fingerprint: fingerprint, Executable: executable, Args: d.Args, Env: d.Env,
		CgroupMemoryMaxBytes: a.cfg.RoleMemoryMaxBytes[role]}
	if a.tsAuthMisplaced(d) {
		return errors.New("ts-auth needs ts_auth_root on this host for its bundle directory and readiness probe")
	}
	secrets, err := a.resolveSecrets(ctx, d)
	if err != nil {
		return err
	}
	roleEnv, err := a.prepareRoleFiles(ctx, d, secrets)
	if err != nil {
		return err
	}
	if len(secrets) != 0 {
		workload.Env = maps.Clone(d.Env)
		if workload.Env == nil {
			workload.Env = map[string]string{}
		}
		maps.Copy(workload.Env, secrets)
	}
	started, certificateExpiry := "running", time.Time{}
	if a.terraBaseMember(d) {
		if workload.Env, certificateExpiry, err = a.prepareTerraBase(ctx, d); err != nil {
			return err
		}
		workload.DrainTimeout, started = terraBaseDrain, "starting"
	}
	if a.tsAuthReplica(d) {
		if workload.Env, err = a.prepareTSAuth(d, secrets); err != nil {
			return err
		}
		workload.DrainTimeout, started = tsAuthDrain, "starting"
	}
	if len(roleEnv) != 0 {
		workload.Env = maps.Clone(workload.Env)
		if workload.Env == nil {
			workload.Env = map[string]string{}
		}
		maps.Copy(workload.Env, roleEnv)
	}
	var latest desiredReply
	if err := a.request(ctx, "desired", struct {
		Role string `json:"role"`
	}{role}, &latest); err != nil {
		return err
	}
	if err := a.validateDesiredReply(latest); err != nil {
		return err
	}
	if !sameDesiredReplyBinding(target, latest) {
		return errors.New("desired target changed before native apply")
	}
	var active cycleReply
	if err := a.request(ctx, "cycle", cycleQuery{Role: role, Digest: d.Digest, Generation: d.Generation, AuthorityEpoch: d.AuthorityEpoch, Attempt: query.Attempt}, &active); err != nil {
		return err
	}
	if active.State != "active" || active.CycleID != cycle.CycleID || active.Fence != cycle.Fence {
		return errors.New("cycle fence changed before native apply")
	}
	if _, _, err := a.executionLease(); err != nil {
		return err
	}
	// The controller requests above took time: launch only on the
	// confirmed filesystem's mount as it is now.
	if a.terraBaseMember(d) && a.cfg.TerraBaseDataVolume {
		if err := a.terraBaseDataVolumeIntact(); err != nil {
			a.terraBaseVolumeConfirmed = ""
			return fmt.Errorf("terrabase data volume changed before launch: %w", err)
		}
	}
	if err := a.runner.Apply(ctx, workload); err != nil {
		return err
	}
	if !certificateExpiry.IsZero() {
		a.terraBase[role] = terraBaseMember{certificateExpiry: certificateExpiry}
	}
	observed, err := a.runner.Observe(ctx, role)
	if err != nil {
		return err
	}
	if !observed.Running || observed.Digest != d.Digest || observed.Fingerprint != fingerprint {
		return errors.New("native workload did not start")
	}
	cycleSucceeded = true
	pending = a.pending[role]
	pending.query.Succeeded = true
	pending.outcomeReady = true
	a.pending[role] = pending
	if err := a.flushCycle(ctx, role); err != nil {
		return err
	}
	if err := a.publishReport(ctx, a.reportFor(d, started, nil)); err != nil {
		return err
	}
	return nil
}

func LoadConfig(path string) (Config, error) {
	if path == "" {
		return Config{}, errors.New("--config is required")
	}
	info, err := os.Stat(path)
	if err != nil {
		return Config{}, fmt.Errorf("stat config: %w", err)
	}
	if info.Size() > maxConfigBytes {
		return Config{}, errors.New("config is too large")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}, fmt.Errorf("read config: %w", err)
	}
	cfg, err := decodeConfig(data)
	if err != nil {
		return Config{}, fmt.Errorf("parse config: %w", err)
	}
	if err := cfg.Observability.Validate(); err != nil {
		return Config{}, fmt.Errorf("observability config: %w", err)
	}
	if api := cfg.Controller.MachinesAPI; api != nil {
		if err := api.Validate(); err != nil {
			return Config{}, err
		}
	}
	return cfg, nil
}

func decodeConfig(data []byte) (Config, error) {
	var cfg Config
	if err := protocol.DecodeStrict(data, &cfg, maxConfigBytes); err != nil {
		return Config{}, err
	}
	if cfg.Version != ConfigVersion {
		return Config{}, fmt.Errorf("config version must be %d, got %d", ConfigVersion, cfg.Version)
	}
	cfg.wire = data
	return cfg, nil
}

func (m *controllerMembership) Run(ctx context.Context) error {
	if m.open != nil {
		for {
			attemptCtx, cancel := context.WithCancel(ctx)
			timer := time.AfterFunc(20*time.Second, cancel)
			opened, err := m.open(attemptCtx)
			stopped := timer.Stop()
			if err == nil && stopped && attemptCtx.Err() == nil {
				defer cancel()
				return opened.Run(attemptCtx)
			}
			if opened != nil && opened.seed != nil {
				opened.seed.server.Close()
			}
			cancel()
			if ctx.Err() != nil {
				return nil
			}
			if err == nil {
				err = context.DeadlineExceeded
			}
			slog.WarnContext(ctx, "controller membership held while verified ledger is unavailable",
				"component", "membership", "error", err)
			select {
			case <-ctx.Done():
				return nil
			case <-time.After(membership.DefaultInterval):
			}
		}
	}
	if m.seed == nil {
		return m.reconciler.Run(ctx)
	}
	runCtx, cancel := context.WithCancel(ctx)
	defer cancel()
	errs := make(chan error, 2)
	go func() { errs <- m.seed.Run(runCtx) }()
	go func() { errs <- m.reconciler.Run(runCtx) }()
	first := <-errs
	cancel()
	return errors.Join(first, <-errs)
}

func (peers natsMembershipPeers) Meta(context.Context) (membership.Meta, error) {
	view, err := peers.runtime.Meta()
	if err != nil {
		return membership.Meta{}, err
	}
	return membershipMeta(view), nil
}

func membershipMeta(view natscell.MetaView) membership.Meta {
	meta := membership.Meta{Leader: view.Leader, Size: view.Size}
	for _, replica := range view.Replicas {
		if replica.Name == view.Self {
			continue
		}
		meta.Peers = append(meta.Peers, membership.Peer{Name: replica.Name,
			Online: !replica.Offline && !replica.Pending, Current: replica.Current,
			Lag: replica.Lag, Active: replica.Active})
	}
	return meta
}

func (replacer *serializedReplacer) Replace(ctx context.Context, action membership.Action) error {
	replacer.mu.Lock()
	defer replacer.mu.Unlock()
	if err := ctx.Err(); err != nil {
		return err
	}
	return replacer.inner.Replace(ctx, action)
}

func natsSeedRequester(conn *nats.Conn, subject string) membership.SeedRequester {
	return func(ctx context.Context, payload []byte) ([]byte, error) {
		if conn == nil || subject == "" {
			return nil, membership.ErrReplacerUnavailable
		}
		reply, err := conn.RequestWithContext(ctx, subject, payload)
		if err != nil {
			if errors.Is(err, nats.ErrNoResponders) {
				return nil, fmt.Errorf("no seed controller serves %s (seed unavailable or controller credentials without the membership.replace grant): %w", subject, err)
			}
			return nil, err
		}
		return reply.Data, nil
	}
}

func (service *seedReplacementService) Run(ctx context.Context) error {
	defer service.server.Close()
	subscription, err := service.conn.Subscribe(service.subject, func(message *nats.Msg) {
		if message.Reply == "" || len(message.Data) == 0 || len(message.Data) > seedRequestMaxBytes {
			return
		}
		// The reply must leave within the credential's five-second
		// response grant; the replacement itself runs in the background.
		requestCtx, cancel := context.WithTimeout(ctx, 3*time.Second)
		defer cancel()
		reply := service.server.Handle(requestCtx, message.Data)
		wire, err := protocol.EncodeJSON(reply)
		if err == nil {
			_ = message.Respond(wire)
		}
	})
	if err != nil {
		return fmt.Errorf("serve controller slot replacement requests: %w", err)
	}
	slog.InfoContext(ctx, "seed serves routed controller slot replacement requests", "component", "membership",
		"subject", service.subject)
	<-ctx.Done()
	_ = subscription.Unsubscribe()
	return nil
}

func (founder *seedFounderRecorder) Replace(ctx context.Context, action membership.Action) error {
	if err := action.Fence(ctx); err != nil {
		return err
	}
	founder.mu.Lock()
	founder.actions = append(founder.actions, action)
	founder.mu.Unlock()
	close(founder.done)
	return nil
}

func (instances seedInstances) Lifecycle(_ context.Context, instance string) (string, error) {
	if state, ok := instances[instance]; ok {
		return state, nil
	}
	return "", errors.New("instance not found")
}

func (forged seedAuthorityAsLeader) Current() authority.Snapshot {
	snapshot := forged.runtime.Current()
	snapshot.Leader, snapshot.Ready, snapshot.Epoch = true, true, forged.epoch
	snapshot.Revision, snapshot.ExpiresAt = 1, time.Now().Add(time.Hour)
	// A follower's snapshot names the lease holder; claim the seed's own.
	snapshot.CandidateID, snapshot.OwnerID = "0000000000Y0WXHAAJ7JVKJYN1", "forged-owner"
	return snapshot
}

