func (replacer SeedRoutedReplacer) Replace(ctx context.Context, action Action) error {
	if replacer.Request == nil || replacer.Leadership == nil {
		return ErrReplacerUnavailable
	}
	snapshot := replacer.Leadership.Current()
	if !snapshot.CanMutate() || action.Epoch == 0 || snapshot.Epoch != action.Epoch {
		return errors.New("controller authority term ended before routing the replacement to the seed")
	}
	// Renew the lease first, so the seed's read-only check sees a fresh
	// record for this exact term.
	if action.Fence != nil {
		if err := action.Fence(ctx); err != nil {
			return fmt.Errorf("authority fence: %w", err)
		}
	}
	payload, err := protocol.EncodeJSON(SeedReplaceRequest{Version: SeedReplaceRequestVersion, Cell: replacer.Cell,
		Slot: action.Slot, PreviousAttempt: action.PreviousAttempt, PriorInstanceOCID: action.PriorInstanceOCID,
		Retirement: action.Retirement.Wire, Epoch: action.Epoch, CandidateID: snapshot.CandidateID,
		OwnerID: snapshot.OwnerID})
	if err != nil {
		return err
	}
	requestCtx, cancel := context.WithTimeout(ctx, seedRequestTimeout)
	defer cancel()
	wire, err := replacer.Request(requestCtx, payload)
	if err != nil {
		return fmt.Errorf("route replacement to the seed controller: %w", err)
	}
	var reply SeedReplaceReply
	if err := protocol.DecodeStrict(wire, &reply, 4<<10); err != nil {
		return fmt.Errorf("decode seed replacement reply: %w", err)
	}
	switch reply.Status {
	case SeedAccepted, SeedInProgress, SeedDone:
		return nil
	case SeedFailed:
		return fmt.Errorf("seed replacement failed: %s", reply.Error)
	case SeedRefused:
		return fmt.Errorf("%w: %s", ErrSeedRefused, reply.Error)
	}
	return fmt.Errorf("seed replacement reply has unknown status %q", reply.Status)
}

func NewSeedServer(ctx context.Context, topology Topology, deps SeedServerDependencies) (*SeedServer, error) {
	if err := topology.Validate(); err != nil {
		return nil, err
	}
	if topology.SelfSlot != topology.SeedSlot {
		return nil, errors.New("only the seed controller serves slot replacement requests")
	}
	if deps.Leases == nil || deps.Instances == nil || deps.Replacer == nil {
		return nil, errors.New("seed replacement server dependencies are incomplete")
	}
	if deps.Logger == nil {
		deps.Logger = slog.Default()
	}
	base, stop := context.WithCancel(context.WithoutCancel(ctx))
	server := &SeedServer{topology: topology, deps: deps, base: base, stop: stop}
	context.AfterFunc(ctx, stop)
	return server, nil
}

func (s *SeedServer) Handle(ctx context.Context, payload []byte) SeedReplaceReply {
	refuse := func(err error) SeedReplaceReply {
		s.deps.Logger.Warn("seed refused a controller slot replacement request", "error", err)
		return SeedReplaceReply{Status: SeedRefused, Error: err.Error()}
	}
	if s.base.Err() != nil {
		return refuse(errors.New("seed controller is stopping"))
	}
	var request SeedReplaceRequest
	if len(payload) == 0 || len(payload) > maxSeedRequestBytes {
		return refuse(errors.New("request size is out of bounds"))
	}
	if err := protocol.DecodeStrict(payload, &request, maxSeedRequestBytes); err != nil {
		return refuse(errors.New("request is not a strict replacement request"))
	}
	if err := request.validate(s.topology); err != nil {
		return refuse(err)
	}
	if err := s.deps.Leases.VerifyLeaseHolder(ctx, request.Epoch, request.CandidateID, request.OwnerID); err != nil {
		return refuse(fmt.Errorf("requesting controller does not hold authority epoch %d: %w", request.Epoch, err))
	}
	key := request.key()
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.base.Err() != nil {
		return refuse(errors.New("seed controller is stopping"))
	}
	if job := s.job; job != nil {
		switch {
		case job.key == key && job.running:
			return SeedReplaceReply{Status: SeedInProgress}
		case job.key == key && job.err != nil && !job.request.sameTerm(request):
			// The term that started the failed attempt ended (its fence
			// most likely cancelled it); the new term resumes at once.
		case job.key == key && job.err != nil:
			// Report the failure once; the leader's retry backoff decides
			// when the next request starts a fresh attempt.
			s.job = nil
			return SeedReplaceReply{Status: SeedFailed, Error: job.err.Error()}
		case job.key == key:
			return SeedReplaceReply{Status: SeedDone}
		case job.running:
			return refuse(fmt.Errorf("seed is already replacing slot %s", job.request.Slot))
		}
	}
	job := &seedJob{key: key, request: request, running: true}
	s.job = job
	s.jobs.Add(1)
	go s.run(job)
	s.deps.Logger.Info("seed accepted a routed controller slot replacement", "slot", request.Slot,
		"previous_attempt", request.PreviousAttempt, "prior_instance", request.PriorInstanceOCID,
		"epoch", request.Epoch, "leader", request.CandidateID)
	return SeedReplaceReply{Status: SeedAccepted}
}

func (s *SeedServer) execute(ctx context.Context, request SeedReplaceRequest, fence func(context.Context) error) error {
	// Independent of the leader's observation: an instance that may still
	// run is never replaced by a routed request.
	lifecycle, err := s.deps.Instances.Lifecycle(ctx, request.PriorInstanceOCID)
	if err != nil {
		return fmt.Errorf("observe prior instance %s: %w", request.PriorInstanceOCID, err)
	}
	if lifecycle != LifecycleTerminated {
		return fmt.Errorf("prior instance %s is %s, not %s", request.PriorInstanceOCID, lifecycle, LifecycleTerminated)
	}
	if err := fence(ctx); err != nil {
		return fmt.Errorf("authority fence: %w", err)
	}
	sum := sha256.Sum256(request.Retirement)
	return s.deps.Replacer.Replace(ctx, Action{Slot: request.Slot, PreviousAttempt: request.PreviousAttempt,
		PriorInstanceOCID: request.PriorInstanceOCID, Epoch: request.Epoch,
		Retirement: Evidence{Slot: request.Slot, PreviousAttempt: request.PreviousAttempt,
			PriorInstanceOCID: request.PriorInstanceOCID, Digest: hex.EncodeToString(sum[:]), Wire: request.Retirement},
		Reason: "routed by authority leader " + request.CandidateID, Fence: fence})
}

func (r *Runtime) VerifyLeaseHolder(ctx context.Context, epoch uint64, candidateID, ownerID string) error {
	if r == nil {
		return ErrNotLeader
	}
	if epoch == 0 || candidateID == "" || ownerID == "" {
		return ErrFenced
	}
	if r.checkClock() != nil {
		return ErrClockUnhealthy
	}
	readCtx, cancel := context.WithTimeout(ctx, authorityAPITimeout)
	defer cancel()
	// The same control-stream check as the leader's own Guard: a stream whose
	// configuration drifted (replicas, retention, limits) fails closed.
	info, err := r.stream.Info(readCtx)
	if err != nil {
		return stageFailure("foreign_lease_stream_info", err)
	}
	if err := verifyControlStreamConfig(info.Config, r.config.Replicas); err != nil {
		return stageFailure("foreign_lease_stream_config", err)
	}
	entry, err := r.stream.GetLastMsgForSubject(readCtx, r.leaseSub)
	if err != nil {
		return stageFailure("foreign_lease_msg_get", err)
	}
	lease, err := decodeLease(entry.Data)
	if err != nil {
		return stageFailure("foreign_lease_decode", ErrLeaseCorrupt)
	}
	if lease.Scope != r.config.Scope || lease.DeploymentID != r.config.DeploymentID || lease.CandidateID != candidateID || lease.OwnerID != ownerID ||
		lease.Epoch != epoch || lease.Released ||
		!time.Now().Before(entry.Time.Add(time.Duration(lease.LeaseDuration))) {
		return ErrFenced
	}
	return nil
}

func Start(ctx context.Context, js jetstream.JetStream, config Config) (*Runtime, error) {
	if js == nil {
		return nil, errors.New("JetStream is required")
	}
	config = config.withDefaults()
	if err := config.validate(); err != nil {
		return nil, err
	}
	if config.ClockCheck != nil && config.ClockCheck() != nil {
		return nil, ErrClockUnhealthy
	}
	logger := config.Logger
	if logger == nil {
		logger = slog.Default()
	}
	stream, err := openControlStream(ctx, js, config.Replicas)
	if err != nil {
		return nil, fmt.Errorf("open authority control log: %w", err)
	}
	readCtx, readCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readStream, err := js.Stream(readCtx, ControlStreamName)
	readCancel()
	if err != nil {
		return nil, fmt.Errorf("open authority read handle: %w", err)
	}
	infoCtx, infoCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readInfo, err := readStream.Info(infoCtx)
	infoCancel()
	if err != nil {
		return nil, fmt.Errorf("inspect authority read handle: %w", err)
	}
	if err := verifyControlStreamConfig(readInfo.Config, config.Replicas); err != nil {
		return nil, fmt.Errorf("validate authority read handle: %w", err)
	}
	loopCtx, cancel := context.WithCancel(ctx)
	runtime := &Runtime{
		js:          js,
		publisher:   js,
		stream:      stream,
		readStream:  readStream,
		config:      config,
		leaseSub:    fmt.Sprintf("%s.%s.lease", controlSubjectRoot, config.Scope),
		ownerID:     entityid.New(),
		logger:      logger,
		diagnostics: authorityDiagnosticQueue,
		diagTimes:   make(map[string]time.Time),
		cancel:      cancel,
		done:        make(chan struct{}),
	}
	runtime.publishSnapshot(Snapshot{Scope: config.Scope, DeploymentID: config.DeploymentID, CandidateID: config.CandidateID, OwnerID: runtime.ownerID, Reason: "not-observed"})
	runtime.logSnapshotTransition()
	var observeErr error
	for attempt := range startupReconcileAttempts {
		observeErr = runtime.reconcileWithRetry(loopCtx)
		runtime.logSnapshotTransition()
		if observeErr != nil && loopCtx.Err() != nil {
			observeErr = loopCtx.Err()
			break
		}
		if observeErr == nil || !retryableStartupReconcileError(loopCtx, observeErr) || attempt+1 == startupReconcileAttempts {
			break
		}
		timer := time.NewTimer(startupReconcileDelay(attempt, observeErr))
		select {
		case <-loopCtx.Done():
			observeErr = loopCtx.Err()
			timer.Stop()
		case <-timer.C:
		}
	}
	if observeErr != nil {
		cancel()
		close(runtime.done)
		return nil, fmt.Errorf("observe authority lease: %w", observeErr)
	}
	go runtime.run(loopCtx)
	return runtime, nil
}

func (r *Runtime) Guard(ctx context.Context, expectedEpoch uint64) error {
	if r == nil {
		return ErrNotLeader
	}
	if guard, ok := ctx.Value(verificationGuardKey{}).(*verificationGuard); ok {
		return r.guardVerification(ctx, expectedEpoch, guard)
	}
	if r.checkClock() != nil {
		return ErrClockUnhealthy
	}
	r.mu.Lock()
	current := r.Current()
	if !current.CanMutate() || current.Scope != r.config.Scope || current.DeploymentID != r.config.DeploymentID || current.CandidateID != r.config.CandidateID || current.OwnerID != r.ownerID {
		wasLocalLeader := current.Leader && current.CandidateID == r.config.CandidateID && current.OwnerID == r.ownerID
		r.mu.Unlock()
		r.logSnapshotTransition()
		if wasLocalLeader {
			r.recordFailure(stageFailure("guard_precondition", ErrNotLeader))
		}
		return ErrNotLeader
	}
	if expectedEpoch == 0 || current.Epoch != expectedEpoch {
		r.mu.Unlock()
		return ErrFenced
	}
	var lastErr error
	for range 8 {
		err := r.guardLocked(ctx, expectedEpoch)
		if !errors.Is(err, ErrConflict) {
			r.mu.Unlock()
			r.logSnapshotTransition()
			if err != nil {
				r.recordFailure(err)
			}
			return err
		}
		lastErr = err
	}
	if lastErr == nil {
		lastErr = stageFailure("guard_retry", ErrConflict)
	}
	r.mu.Unlock()
	r.logSnapshotTransition()
	r.recordFailure(lastErr)
	return lastErr
}

func (r *Runtime) guardLocked(ctx context.Context, expectedEpoch uint64) error {
	info, err := r.stream.Info(ctx)
	if err != nil {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Reason: "control-log-unavailable"})
		return stageFailure("guard_stream_info", err)
	}
	if err := verifyControlStreamConfig(info.Config, r.config.Replicas); err != nil {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Reason: "control-log-incompatible"})
		return stageFailure("guard_stream_config", err)
	}
	entry, err := r.stream.GetLastMsgForSubject(ctx, r.leaseSub)
	if err != nil {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Reason: "lease-unreadable"})
		return stageFailure("guard_lease_msg_get", err)
	}
	if entry.Sequence > info.State.LastSeq {
		return stageFailure("guard_sequence_check", ErrConflict)
	}
	lease, err := decodeLease(entry.Data)
	if err != nil {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Reason: "lease-corrupt"})
		return stageFailure("guard_lease_decode", ErrLeaseCorrupt)
	}
	if lease.Scope != r.config.Scope || lease.DeploymentID != r.config.DeploymentID || lease.CandidateID != r.config.CandidateID || lease.OwnerID != r.ownerID || lease.Epoch != expectedEpoch || lease.Released || !time.Now().Before(entry.Time.Add(time.Duration(lease.LeaseDuration))) {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: lease.DeploymentID, CandidateID: lease.CandidateID, OwnerID: lease.OwnerID, Epoch: lease.Epoch, Revision: entry.Sequence, ObservedAt: time.Now(), Reason: "lease-fenced"})
		return stageFailure("guard_lease_check", ErrFenced)
	}
	return r.appendLease(ctx, info.State.LastSeq, entry.Sequence, expectedEpoch, false)
}

func ControllerSubscriptions(cell string) []string {
	return []string{
		protocol.BrokerClaimApplySubject(cell), protocol.AgentObservation(cell, "*", "*"),
		protocol.DeliveryArtifactAdmitSubject(cell), protocol.HostRegisterSubject(cell),
		protocol.PlacementApplySubject(cell), protocol.ManagedUpdatePrepareSubject(cell),
		protocol.BackupOperationSubject(cell), protocol.TerminalSubject(cell, ">"),
		// The seed answers epoch-fenced slot replacement requests from a
		// non-seed authority leader. Material issued before this grant
		// existed lacks it; the request then has no responder and the
		// leader holds the slot, as before.
		protocol.MembershipReplaceSubject(cell),
		// Every controller collects its peers' signed rollout health proofs
		// (controller.rollouts.executor). Material issued before this grant
		// lacks it; such a controller sees no proofs, so its executor holds
		// every rollout in preflight and nothing moves.
		protocol.RolloutProofSubject(cell, ""),
		// Read-only query services this region answers for every region.
		protocol.Regional(cell, "query", ">"),
		// The global home builds the roster from every region's heartbeat.
		// Material issued before this grant lacks it; the home then keeps no
		// roster, and its peers keep their last one.
		protocol.AnyRegionHealthSubject(),
		// Every region's dashboard rollup (TS-805), carried by the link.
		// Material issued before this grant lacks it; such a follower's
		// global view stays empty and the leader holds only its own rollup.
		protocol.RegionRollupGrant,
	}
}

func startMembershipCluster(t *testing.T, ctx context.Context) *membershipCluster {
	t.Helper()
	root := t.TempDir()
	tlsFiles, routePassword := testR3TLSMaterial(t, root)
	opKey, _ := nkeys.CreateOperator()
	sysKey, _ := nkeys.CreateAccount()
	cellKey, _ := nkeys.CreateAccount()
	opID, _ := opKey.PublicKey()
	sysID, _ := sysKey.PublicKey()
	cellID, _ := cellKey.PublicKey()
	op := jwt.NewOperatorClaims(opID)
	op.SystemAccount = sysID
	opRaw, err := op.Encode(opKey)
	if err != nil {
		t.Fatal(err)
	}
	sysRaw, err := jwt.NewAccountClaims(sysID).Encode(opKey)
	if err != nil {
		t.Fatal(err)
	}
	cell := jwt.NewAccountClaims(cellID)
	cell.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: 64 << 20, DiskStorage: 512 << 20, Streams: 10, Consumer: 10}
	cellRaw, err := cell.Encode(opKey)
	if err != nil {
		t.Fatal(err)
	}
	write := func(name, raw string) string {
		path := filepath.Join(root, name)
		if err := os.WriteFile(path, []byte(raw), 0o600); err != nil {
			t.Fatal(err)
		}
		return path
	}
	opFile, sysFile, cellFile := write("operator.jwt", opRaw), write("system.jwt", sysRaw), write("cell.jwt", cellRaw)
	ticketPub, _ := testEd25519(t, root, "membership-ticket.key")
	ticketFile := write("membership-ticket.pub", base64.StdEncoding.EncodeToString(ticketPub))
	ids := []string{"broker-a", "broker-b", "broker-c"}
	ports := reserveControllerPorts(t, 2*len(ids))
	clientPorts, routePorts := ports[:len(ids)], ports[len(ids):]
	cluster := &membershipCluster{ids: ids, root: root, configs: make([]natscell.Config, len(ids)),
		runtimes: make([]*natscell.Runtime, len(ids)), membership: make([]string, len(ids))}
	for index, id := range ids {
		var routes []string
		for peer, port := range routePorts {
			if peer != index {
				routes = append(routes, fmt.Sprintf("nats-route://127.0.0.1:%d", port))
			}
		}
		controllerPub, controllerCreds := testBrokerJWTUser(t, root, id+"-controller.creds", cellKey, cellID,
			[]string{"$JS.API.>", "$JS.ACK.>", "ts.membership.>"}, nil)
		controllerClaim, err := jwt.DecodeUserClaims(testDecoratedJWT(t, controllerCreds))
		if err != nil {
			t.Fatal(err)
		}
		controllerClaim.Sub.Allow = jwt.StringList{"ts.orch.v1.gru.inbox." + controllerPub + ".>"}
		controllerCreds = testBrokerJWTUserWithClaim(t, root, id+"-controller.creds", cellKey, controllerClaim)
		systemPub, systemCreds := testBrokerJWTUser(t, root, id+"-system.creds", sysKey, sysID,
			[]string{"$SYS.REQ.ACCOUNT." + cellID + ".CLAIMS.UPDATE"}, nil)
		systemClaim, err := jwt.DecodeUserClaims(testDecoratedJWT(t, systemCreds))
		if err != nil {
			t.Fatal(err)
		}
		systemClaim.Sub.Allow = jwt.StringList{"ts.orch.v1.gru.inbox." + systemPub + ".>"}
		systemCreds = testBrokerJWTUserWithClaim(t, root, id+"-system.creds", sysKey, systemClaim)
		memberPub, memberCreds := testBrokerJWTUser(t, root, id+"-membership.creds", sysKey, sysID,
			[]string{natscell.MembershipServerRemoveSubject, natscell.MembershipMetaStepdownSubject}, nil)
		memberClaim, err := jwt.DecodeUserClaims(testDecoratedJWT(t, memberCreds))
		if err != nil {
			t.Fatal(err)
		}
		memberClaim.Sub.Allow = jwt.StringList{"ts.orch.v1.gru.inbox." + memberPub + ".>"}
		cluster.membership[index] = testBrokerJWTUserWithClaim(t, root, id+"-membership.creds", sysKey, memberClaim)
		cluster.configs[index] = natscell.Config{Cell: "gru", Instance: id, Replicas: 3,
			CredentialsFile: controllerCreds, TLS: tlsFiles,
			Embedded: &natscell.Embedded{Host: "127.0.0.1", Port: clientPorts[index], RouteHost: "127.0.0.1",
				RoutePort: routePorts[index], Routes: routes, StoreDir: filepath.Join(root, id),
				StoreMaxBytes: 1 << 30, TLS: tlsFiles, RouteTLS: tlsFiles, RouteUser: "membership-route",
				RoutePasswordFile: routePassword, OperatorJWTFile: opFile, SystemJWTFile: sysFile,
				CellJWTFile: cellFile, SystemCredentialsFile: systemCreds,
				TicketPublicKeyFile: ticketFile, MembershipCredentialsFile: cluster.membership[index],
				BrokerIDs: ids}}
	}
	errs := make([]error, len(ids))
	var starts sync.WaitGroup
	for index := range ids {
		starts.Go(func() { cluster.runtimes[index], errs[index] = natscell.Start(ctx, cluster.configs[index]) })
	}
	starts.Wait()
	t.Cleanup(func() {
		cluster.mu.Lock()
		defer cluster.mu.Unlock()
		for _, runtime := range cluster.runtimes {
			if runtime != nil {
				_ = runtime.Close()
			}
		}
	})
	for index, err := range errs {
		if err != nil {
			t.Fatalf("start %s: %v", ids[index], err)
		}
	}
	for _, runtime := range cluster.runtimes {
		if err := runtime.WaitForCluster(ctx, 3); err != nil {
			t.Fatal(err)
		}
	}
	waitMembership(t, ctx, "full R3 readiness", func() bool {
		for _, runtime := range cluster.runtimes {
			if !runtime.FullClusterReady(3) {
				return false
			}
		}
		return true
	})
	return cluster
}

