func (fake *fakeSlotOCI) Slots(_ context.Context, slots []string) (map[string]membership.LedgerSlot, error) {
	fake.mu.Lock()
	defer fake.mu.Unlock()
	out := make(map[string]membership.LedgerSlot, len(slots))
	for _, slot := range slots {
		out[slot] = fake.ledger[slot]
	}
	return out, nil
}

func (fake *fakeSlotOCI) Lifecycle(_ context.Context, instance string) (string, error) {
	fake.mu.Lock()
	defer fake.mu.Unlock()
	if state, ok := fake.lifecycle[instance]; ok {
		return state, nil
	}
	return "", fmt.Errorf("instance %s not found", instance)
}

func (fake *fakeSlotOCI) Evidence(context.Context) (map[string]membership.Evidence, error) {
	fake.mu.Lock()
	defer fake.mu.Unlock()
	return copyEvidence(fake.evidence), nil
}

func copyEvidence(in map[string]membership.Evidence) map[string]membership.Evidence {
	out := make(map[string]membership.Evidence, len(in))
	for key, value := range in {
		out[key] = value
	}
	return out
}

func (fake *fakeSlotOCI) Replace(ctx context.Context, action membership.Action) error {
	fake.mu.Lock()
	fake.replaced = append(fake.replaced, action)
	relaunch := fake.relaunch
	fake.mu.Unlock()
	instance, err := relaunch(ctx, action)
	if err != nil {
		return err
	}
	fake.mu.Lock()
	defer fake.mu.Unlock()
	fake.ledger[action.Slot] = membership.LedgerSlot{Attempt: action.PreviousAttempt + 1, InstanceOCID: instance,
		Complete: true, Retirement: action.Retirement.Digest}
	fake.lifecycle[instance] = membership.LifecycleRunning
	return nil
}

func (r *Reconciler) Tick(ctx context.Context) error {
	snapshot := r.deps.Leadership.Current()
	if !snapshot.CanMutate() {
		r.reset(0)
		return nil
	}
	r.mu.Lock()
	if r.epoch != snapshot.Epoch {
		// A new term starts every grace period from its own observations.
		r.state, r.epoch = State{Slots: make(map[string]SlotStatus)}, snapshot.Epoch
		r.requested = make(map[string]retirementRequestMark)
	}
	previous := r.state.clone()
	r.mu.Unlock()
	observation, err := r.observe(ctx)
	if err != nil {
		return err
	}
	next, actions := Decide(r.topology, previous, observation)
	for _, action := range actions {
		next.Slots[action.Slot] = r.execute(ctx, snapshot.Epoch, action, next.Slots[action.Slot], observation.At)
	}
	r.requestRetirements(ctx, snapshot.Epoch, next, observation)
	r.commit(snapshot.Epoch, previous, next)
	return nil
}

func (r *Reconciler) observe(ctx context.Context) (Observation, error) {
	meta, err := r.deps.Peers.Meta(ctx)
	if err != nil {
		return Observation{}, fmt.Errorf("read JetStream metadata peers: %w", err)
	}
	ledger, err := r.deps.Ledger.Slots(ctx, r.topology.Slots)
	if err != nil {
		return Observation{}, fmt.Errorf("read controller slot ledger: %w", err)
	}
	lifecycle := make(map[string]string, len(ledger))
	for _, slot := range r.topology.Slots {
		pinned := ledger[slot]
		if slot == r.topology.SelfSlot || pinned.InstanceOCID == "" {
			continue
		}
		state, err := r.deps.Instances.Lifecycle(ctx, pinned.InstanceOCID)
		if err != nil {
			if ctx.Err() != nil {
				return Observation{}, ctx.Err()
			}
			// An unobservable instance is held, never assumed terminated.
			r.deps.Logger.Debug("controller slot instance unobservable", "slot", slot, "error", err)
			continue
		}
		lifecycle[slot] = state
	}
	evidence, err := r.deps.Evidence.Evidence(ctx)
	if err != nil {
		return Observation{}, fmt.Errorf("read retirement evidence: %w", err)
	}
	return Observation{At: r.deps.Now().UTC(), Meta: meta, Ledger: ledger, Lifecycle: lifecycle,
		Evidence: evidence}, nil
}

func (r *Reconciler) execute(ctx context.Context, epoch uint64, action Action, status SlotStatus,
	at time.Time,
) SlotStatus {
	fail := func(err error) SlotStatus {
		status.LastFailure, status.LastError = at, err.Error()
		r.deps.Logger.Warn("controller slot replacement failed", "slot", action.Slot,
			"previous_attempt", action.PreviousAttempt, "error", err)
		return status
	}
	unavailable := func() SlotStatus {
		// Report the decision, but do not hold the single replacement slot.
		status = fail(ErrReplacerUnavailable)
		status.Phase, status.Reason, status.PendingAttempt = PhaseHeld, ErrReplacerUnavailable.Error(), 0
		return status
	}
	if r.deps.Replacer == nil {
		return unavailable()
	}
	if err := r.deps.Leadership.Guard(ctx, epoch); err != nil {
		return fail(fmt.Errorf("authority fence: %w", err))
	}
	r.deps.Logger.Info("replacing controller slot", "slot", action.Slot, "previous_attempt", action.PreviousAttempt,
		"prior_instance", action.PriorInstanceOCID, "reason", action.Reason, "epoch", epoch)
	// The term's fence extends through the whole replacement: the context
	// ends as soon as this controller stops holding the epoch, and the
	// replacer rechecks the guard right before each mutation.
	fencedCtx, stopFence := r.termContext(ctx, epoch)
	defer stopFence()
	action.Epoch = epoch
	action.Fence = func(fenceCtx context.Context) error { return r.deps.Leadership.Guard(fenceCtx, epoch) }
	if err := r.deps.Replacer.Replace(fencedCtx, action); err != nil {
		if errors.Is(err, ErrReplacerUnavailable) {
			return unavailable()
		}
		return fail(err)
	}
	status.LastFailure, status.LastError = timeZero, ""
	r.recordReplacement(ctx, epoch, action)
	return status
}

func (r *Runtime) Meta() (MetaView, error) {
	if r == nil || r.server == nil {
		return MetaView{}, errors.New("embedded regional NATS server is unavailable")
	}
	if !r.server.Running() {
		return MetaView{}, errors.New("embedded regional NATS server is not running")
	}
	info, err := r.server.Jsz(nil)
	if err != nil {
		return MetaView{}, fmt.Errorf("read JetStream metadata: %w", err)
	}
	if info.Meta == nil {
		return MetaView{}, errors.New("JetStream metadata group is not clustered")
	}
	view := MetaView{Self: r.server.Name(), Leader: info.Meta.Leader, Size: info.Meta.Size}
	view.Replicas = metaReplicas(info.Meta.Replicas)
	return view, nil
}

func ValidateMembershipCredentials(path, cell, systemAccount string) error {
	if !cellName.MatchString(cell) || systemAccount == "" {
		return errors.New("membership credential cell or system account is invalid")
	}
	claim, public, err := credentialUser(path)
	if err != nil {
		return fmt.Errorf("membership credentials: %w", err)
	}
	publishes := slices.Clone([]string(claim.Pub.Allow))
	slices.Sort(publishes)
	if credentialAccount(claim) != systemAccount ||
		!slices.Equal(publishes, []string{MembershipMetaStepdownSubject, MembershipServerRemoveSubject}) ||
		len(claim.Pub.Deny) != 0 || len(claim.Sub.Allow) != 1 ||
		claim.Sub.Allow[0] != inboxPrefix(cell, public)+".>" || len(claim.Sub.Deny) != 0 ||
		claim.Resp != nil {
		return errors.New("membership credentials must have only server-remove, metadata step-down and private reply grants")
	}
	return nil
}

func (r *Runtime) OpenMembershipAdmin(path string) (*MembershipAdmin, error) {
	if r == nil || r.server == nil || r.resolver == nil || r.operator == nil {
		return nil, errors.New("production membership administration is unavailable")
	}
	if err := ValidateMembershipCredentials(path, r.cell, r.resolver.system); err != nil {
		return nil, err
	}
	_, public, err := credentialUser(path)
	if err != nil {
		return nil, err
	}
	inbox := inboxPrefix(r.cell, public)
	options := []nats.Option{nats.UserCredentials(path), nats.InProcessServer(r.server),
		nats.CustomInboxPrefix(inbox), nats.Name("ts-orch-membership"), nats.NoReconnect(), nats.ErrorHandler(ErrorHandler)}
	conn, err := nats.Connect(r.server.ClientURL(), options...)
	if err != nil {
		return nil, fmt.Errorf("connect membership system user: %w", err)
	}
	return &MembershipAdmin{conn: conn, inbox: inbox}, nil
}

func (a *MembershipAdmin) StepDownMetaLeader(ctx context.Context) error {
	return a.request(ctx, MembershipMetaStepdownSubject, nil)
}

func (a *MembershipAdmin) request(ctx context.Context, subject string, body []byte) error {
	if a == nil || a.conn == nil {
		return errors.New("membership administration is closed")
	}
	requestCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	message, err := a.conn.RequestWithContext(requestCtx, subject, body)
	if err != nil {
		return fmt.Errorf("request %s: %w", subject, err)
	}
	return membershipAPIError(subject, message.Data)
}

func runController(ctx context.Context, cfg Config, output io.Writer) (err error) {
	// Take the systemd notification socket before any child process starts.
	notifier := sdnotify.FromEnvironment()
	defer func() { _ = notifier.Stopping() }()
	telemetry, err := startRuntimeObservability(ctx, cfg, "controller", cfg.NATS.Instance)
	if err != nil {
		return fmt.Errorf("start controller observability: %w", err)
	}
	defer telemetry.close()
	clockProbe := controllerBrokerClockProbe()
	clockCheck := controllerClockCheck(clockProbe)
	admission, err := startControllerAdmission(ctx, cfg, clockCheck)
	if err != nil {
		return err
	}
	defer admission.stop()
	if cfg.NATS.Embedded == nil {
		return errors.New("controller run requires an embedded regional NATS server")
	}
	artifactStoreMaxBytes := cfg.Controller.ArtifactStoreMaxBytes
	if artifactStoreMaxBytes < 0 {
		return errors.New("controller artifact_store_max_bytes must be positive when set")
	}
	if artifactStoreMaxBytes == 0 {
		artifactStoreMaxBytes = delivery.DefaultArtifactStoreMaxBytes
	}
	storeLimitBytes := cfg.NATS.Embedded.StoreLimitBytes()
	if storeLimitBytes < artifactStoreMaxBytes || storeLimitBytes-artifactStoreMaxBytes < controlStoreHeadroomBytes {
		return fmt.Errorf("embedded NATS store_max_bytes must leave at least %d bytes for control state beyond artifact_store_max_bytes", controlStoreHeadroomBytes)
	}
	managed, err := loadManagedControllerConfig(cfg)
	if err != nil {
		return err
	}
	// A managed TerraBase controller needs no generic delivery profile.
	if managed == nil && len(cfg.Controller.Workloads) == 0 {
		return errors.New("controller requires a managed placement config or explicit workload profiles")
	}
	if err := validateWorkloadProfiles(cfg.NATS.Cell, cfg.Controller.Workloads); err != nil {
		return err
	}
	if err := validateAutoscaleConfig(cfg.Controller.Autoscale, cfg.Controller.Workloads); err != nil {
		return err
	}
	policy, err := buildSignerPolicy(cfg)
	if err != nil {
		return err
	}
	memberRole := ""
	if managed != nil {
		memberRole = managed.placement.MemberRole
	}
	services, err := newSpecRegistry(cfg, memberRole)
	if err != nil {
		return err
	}

func newSpecRegistry(cfg Config, memberRole string) (*specRegistry, error) {
	r := &specRegistry{cell: cfg.NATS.Cell, fixed: map[string]WorkloadProfile{},
		signers: slices.SortedFunc(slices.Values(cfg.Controller.TrustedSigners), func(a, b TrustedSignerConfig) int {
			return strings.Compare(a.Actor, b.Actor)
		}), terraBaseCA: cfg.Controller.TerraBaseCACertFile != "",
		signedArtifactStore: cmp.Or(cfg.Controller.ArtifactStoreMaxBytes, delivery.DefaultArtifactStoreMaxBytes)}
	if cfg.NATS.Embedded != nil {
		r.artifactStoreLimit = cfg.NATS.Embedded.StoreLimitBytes() - specStoreHeadroomBytes
	}
	if _, signed := cfg.Controller.Workloads[terrabase.Role]; signed {
		r.terraBaseCA = true
	}
	if reconcile := cfg.Controller.OciReconcile; reconcile != nil {
		r.signedDesired, r.publicLB = reconcile.Desired, reconcile.PublicLB
	}
	if memberRole != "" {
		r.reserved = append(r.reserved, memberRole)
	}
	autoscaleConfig := cfg.Controller.Autoscale
	if err := r.loadTrust(cfg); err != nil {
		return nil, err
	}

func (r *specRegistry) loadTrust(cfg Config) error {
	if cfg.Controller.SpecTrust != nil {
		return errors.New("production controller uses the image trust roots")
	}
	accepted, inputs, err := specAcceptedInputs()
	if err != nil {
		return fmt.Errorf("load accepted trust roots for cell specs: %w", err)
	}
	identity := cellspec.Identity{DeploymentID: accepted.DeploymentID,
		Cell: strings.ToLower(accepted.Cell), Environment: accepted.Environment}
	if identity.Cell != cfg.NATS.Cell {
		return errors.New("accepted trust cell differs from the controller cell")
	}
	if err := identity.Validate(); err != nil {
		return err
	}
	r.identity = identity
	return r.openRoots(inputs.Genesis, inputs.Chain, bootstrapstart.RootChainFile)
}

